async function relationOptions(fields){
  const result={};
  const defs=fields.filter(f=>f[2]==='relation');
  await Promise.all(defs.map(async f=>{const cfg=f[3]||{}; result[f[0]]=await api(`/api/${cfg.source}?assessment_id=${activeAssessmentId}`);}));
  return result;
}
function relationLabel(row,cfg){
  if(cfg.format==='gap') return `#${row.id} · ${row.severity||''} · ${row.description||''}`;
  const text=row[cfg.label]||`#${row.id}`;
  return `#${row.id} · ${text}`;
}
async function entityView(key){
  const c=configs[key];
  if(key!=='assessments'&&!activeAssessmentId){const a=await getActiveAssessment();if(!a){$('#content').innerHTML='<div class="notice">Create an assessment first.</div>';return;}}
  const rows=await api(scopedUrl(key));
  const edit=editingRecord&&editingRecord.key===key?rows.find(r=>r.id===editingRecord.id):null;
  const displayFields=edit?c.fields.filter(f=>!(f[3]?.createOnly)):c.fields;
  const relations=await relationOptions(displayFields);
  const immutable=key==='decisions';
  const defaults=edit||{};
  const canCreate=c.allowCreate!==false;
  const integrityNotice=key!=='assessments'?'<div class="subtle" style="margin-bottom:10px">Assessment ownership is controlled by the active assessment. Related records are limited to this assessment and cannot be reassigned across assessments.</div>':'';
  const evidenceNotice=key==='evidence'?'<div class="subtle" style="margin-bottom:10px">Verification and lifecycle are separate controls. Validity is set when evidence is created; once stale, restoring Current status requires the governed Lifecycle Review action.</div>':'';
  const editor=(!canCreate&&!edit)?`<div class="notice"><strong>Accountable acceptance only.</strong><br>Accepted-risk records are created automatically from an authorized Executive Decision of <em>Accept Risk</em>. They cannot be deleted; close or supersede them with a documented basis.</div>`:`<div class="section-title"><h2>${edit?'Edit':'New'} ${c.title}</h2>${edit?'<button class="btn secondary" type="button" onclick="cancelEdit()">Cancel</button>':''}</div>${integrityNotice}${evidenceNotice}${immutable?'<div class="subtle" style="margin-bottom:10px">Executive decisions are append-only records. An Accept Risk decision requires a named authority, explicit residual exposure, and review date; it automatically creates an accountable Accepted Risk record.</div>':''}<form id="entity-form">${formHtml(displayFields,defaults,relations)}<div class="form-actions"><button class="btn">${edit?'Update':'Save'} ${c.title}</button></div></form>`;
  if(key==='assessments'){
    const assessmentAttention=rows.filter(r=>['Due','Overdue','Stale'].some(term=>String(r.reassessment_lifecycle_status||'').includes(term)));
    $('#content').innerHTML=`<div class="card"><span class="subtle">SalTHIRA™ · Identify risk and establish priorities</span><h2>Risk assessment workspaces</h2><p>Review current assessment work, see when reassessment needs attention, or start a governed assessment. Authorized people decide priorities and actions.</p></div><div class="section-title"><h2>Needs Your Attention</h2><span class="subtle">Reassessment records shown only when their lifecycle is due, overdue, or stale</span></div>${assessmentAttention.length?entityTable(key,c,assessmentAttention):'<div class="notice">No assessment reassessment lifecycle currently needs attention.</div>'}<div class="section-title"><h2>Current Work</h2><span class="subtle">${rows.length} assessment workspaces</span></div>${entityTable(key,c,rows)}<details ${edit?'open':''}><summary>${edit?'Update selected assessment':'Start a new risk assessment'}</summary><div class="card">${editor}</div></details><div class="notice" style="margin-top:16px"><strong>What happens next:</strong> SalTHIRA records evidence-based risk and priorities. Authorized people retain assessment, decision, approval, and operational authority.</div>`;
    if(systemMode.package_handoff_candidate_available && currentRole==='Client Executive' && rows.some(r=>r.id===activeAssessmentId)){
      const panel=document.createElement('div'); panel.className='card'; panel.style.marginTop='16px'; panel.innerHTML=`<h2>Connect a Protection Advisor receipt</h2><p>Use the one-time code shared by the prospect for this selected assessment. This sends the receipt to Salus for identity, authority and scope review. It does not approve a package or a price.</p><form id="advisor-handoff-claim"><label data-guidance-enhanced="true">One-time code<input name="claim_code" type="text" required autocomplete="off" maxlength="120"></label><label class="advisor-confirm" data-guidance-enhanced="true"><input name="confirm_requested_boundary" type="checkbox" required> I have selected the assessment whose requested operation and exclusions should be compared with this receipt.</label><div class="form-actions"><button class="btn">Send for Salus review</button></div></form><div id="advisor-handoff-result" role="status" aria-live="polite"></div>`;
      $('#content').appendChild(panel);
      panel.querySelector('form').onsubmit=async event=>{
        event.preventDefault(); const form=event.currentTarget, button=form.querySelector('button'), status=panel.querySelector('#advisor-handoff-result');
        const claimCode=String(new FormData(form).get('claim_code')||'').trim(); if(!claimCode)return;
        button.disabled=true; status.textContent='Checking the one-time code…';
        try{
          const result=await api(`/api/assessments/${activeAssessmentId}/advisor-package-handoff`,{method:'POST',body:JSON.stringify({claim_code:claimCode,confirm_requested_boundary:true})});
          form.reset(); status.textContent=result.status||'Sent to Salus for review.';
        }catch(error){status.textContent='The code could not be used for this assessment. Check that it is current and contact Salus if you need help.';}
        finally{button.disabled=false;}
      };
      const quotePanel=document.createElement('div'); quotePanel.className='card'; quotePanel.style.marginTop='16px';
      quotePanel.innerHTML='<h2>Your package quote</h2><p>Loading the current quote for this assessment…</p>';
      $('#content').appendChild(quotePanel);
      try{
        const quote=await api(`/api/assessments/${activeAssessmentId}/package-quote`);
        if(quote.status==='Awaiting Salus signer review'){
          quotePanel.innerHTML='<h2>Your package quote</h2><p>Salus is checking who may review and decide on this quote for the selected operation. The terms and written agreement will appear for that person after the review. No purchase or work has started.</p>';
        }else{
        const fee=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(quote.fee_cents)/100);
        const currentQuote=quote.status==='Quoted' || quote.status==='Authorized';
        const quoteHeading=currentQuote?'Your package quote':'Previous package quote — no current offer';
        const statusNotice=currentQuote?'':'<p class="notice">This quote is historical. Salus must review the changed scope or issue a new written quote before a new decision.</p>';
        quotePanel.innerHTML=`<h2>${quoteHeading}</h2>${statusNotice}<p><strong>${esc(quote.status)}</strong> · Level ${Number(quote.level)}${esc(quote.band)} ${esc(quote.variant||'')} · ${fee}</p><p><strong>Covered work:</strong> ${esc(quote.covered_operation)}<br><strong>Excluded:</strong> ${esc(quote.exclusions)}<br><strong>Included:</strong> ${esc(quote.included_work)}<br><strong>Reports:</strong> ${esc(quote.report_deliverables)}</p><p><strong>Your inputs:</strong> ${esc(quote.member_inputs)}<br><strong>Evidence and clarification:</strong> ${esc(quote.evidence_allowance)}; ${esc(quote.clarification_allowance)}</p><p><strong>Valid through:</strong> ${esc(fmtPackageDate(quote.valid_until))}<br><strong>Start and delivery:</strong> ${esc(fmtPackageDate(quote.start_date))} / ${esc(fmtPackageDate(quote.delivery_date))}<br><strong>Changes:</strong> ${esc(quote.change_triggers)}</p><p>Separate SalOPS services require their own quote. Read the exact agreement before making any decision.</p><a href="/api/package-agreements/${Number(quote.agreement_artifact_id)}/download" target="_blank" rel="noopener">Download the ${currentQuote?'written':'historical'} agreement</a>`;
        if(quote.status==='Quoted'){
          const approvalPanel=document.createElement('section');
          approvalPanel.className='card';
          approvalPanel.style.marginTop='16px';
          approvalPanel.innerHTML='<h3>Approve your agreement online</h3><p>First open and save the agreement above. Check that the covered work, exclusions and amount are correct. By approving, you attest that you can enter this agreement for the covered organization.</p><form id="package-agreement-approval"><label><input type="checkbox" name="reviewed" required> I have read the agreement and this exact quote.</label><label><input type="checkbox" name="authority" required> I am authorized to approve for the organization and agree to use this electronic record.</label><div class="form-actions"><button class="btn" type="submit">Approve agreement</button></div><p role="status" aria-live="polite"></p></form>';
          quotePanel.appendChild(approvalPanel);
          const approvalForm=approvalPanel.querySelector('form');
          const idempotencyKey=window.crypto.randomUUID().replace(/-/g,'');
          approvalForm.onsubmit=async event=>{
            event.preventDefault();
            if(!approvalForm.reportValidity())return;
            const button=approvalForm.querySelector('button');
            const status=approvalForm.querySelector('[role="status"]');
            button.disabled=true;
            status.textContent='Recording your approval…';
            try{
              await api('/api/assessments/'+activeAssessmentId+'/package-acceptance',{
                method:'POST',
                body:JSON.stringify({
                  quote_id:Number(quote.id),
                  quote_sha256:String(quote.content_sha256),
                  agreement_sha256:String(quote.agreement_sha256),
                  member_authority_basis:'I confirm I am authorized to approve this agreement for the covered organization.',
                  idempotency_key:idempotencyKey,
                  accept_quote_and_agreement:true
                })
              });
              status.textContent='Agreement approved. Checking the next step…';
              await render();
            }catch(error){
              const detail=String(error.message||'');
              status.textContent=detail.includes('Download the exact agreement')
                ?'Open and save the agreement above, then try again.'
                :detail.includes('superseded')||detail.includes('version does not match')
                  ?'The agreement or scope changed. Refresh this page and review the current quote.'
                  :'Approval could not be recorded. No payment was taken. Please try again or contact Salus.';
              button.disabled=false;
            }
          };
        }
        if(quote.status==='Authorized'){
          const paymentPanel=document.createElement('div');paymentPanel.className='card';paymentPanel.style.marginTop='16px';
          paymentPanel.innerHTML='<h2>Secure package payment</h2><p>Checking the payment for this exact accepted quote…</p>';
          $('#content').appendChild(paymentPanel);
          let verifiedPaid=false;
          try{
            const payment=await api(`/api/assessments/${activeAssessmentId}/package-checkout`);
            verifiedPaid=payment.status==='Paid';
            if(verifiedPaid){
              paymentPanel.innerHTML=`<h2>Payment verified</h2><p>Your payment matches this accepted Level ${Number(quote.level)}${esc(quote.band)} package and ${fee} quote.</p><p><a href="${esc(payment.receipt_url)}" target="_blank" rel="noopener">View and print your confidential payment receipt</a></p>`;
            }else{
              paymentPanel.innerHTML=`<h2>Complete your package payment</h2><p>Your accepted Level ${Number(quote.level)}${esc(quote.band)} package is ${fee}. Payment is handled by Stripe for this exact quote. The records request opens after Salus verifies payment.</p><button class="btn" type="button" id="start-package-checkout">Continue to secure checkout</button><p id="package-checkout-message" role="status" aria-live="polite"></p>`;
              paymentPanel.querySelector('#start-package-checkout').onclick=async event=>{
                const button=event.currentTarget,status=paymentPanel.querySelector('#package-checkout-message');
                button.disabled=true;status.textContent='Preparing the secure checkout…';
                try{
                  const result=await api(`/api/assessments/${activeAssessmentId}/package-checkout`,{method:'POST'});
                  if(result.status==='Paid'){render();return;}
                  const destination=new URL(result.checkout_url);
                  if(destination.protocol!=='https:'||destination.hostname!=='checkout.stripe.com')
                    throw new Error('Unexpected checkout destination');
                  window.location.assign(destination.href);
                }catch(error){
                  status.textContent='Secure checkout is unavailable. No payment was taken here. Contact Salus for help.';
                  button.disabled=false;
                }
              };
            }
          }catch(error){
            paymentPanel.innerHTML='<h2>Secure package payment</h2><p>Payment status is temporarily unavailable. The records request remains closed. Please contact Salus for help.</p>';
          }
          if(verifiedPaid){
          const intakePanel=document.createElement('div'); intakePanel.className='card'; intakePanel.style.marginTop='16px';
          $('#content').appendChild(intakePanel);
          try{
            const intake=await api(`/api/assessments/${activeAssessmentId}/package-intake`);
            intakePanel.innerHTML=`<h2>Your Level 1 records request</h2><p>Salus has selected only the items needed for your agreed scope. An existing equivalent or short description is fine. If you do not have an item, tell us below. Do not enter personal directories, passwords, medical records or sensitive plans here.</p>${intake.items.length?intake.items.map(item=>`<section class="notice" style="margin-bottom:12px"><h3>${esc(item.title)}</h3><p><strong>Why:</strong> ${esc(item.decision_use)}<br><strong>Requested:</strong> ${esc(item.requested_form)}<br><strong>Equivalent:</strong> ${esc(item.acceptable_equivalent)}<br><strong>Status:</strong> <span id="intake-status-${Number(item.id)}">${esc(item.status)}</span></p><div class="row-actions">${['Not held','Not known','Prefer to discuss'].map(status=>`<button class="btn secondary" type="button" data-intake-id="${Number(item.id)}" data-intake-status="${esc(status)}">${esc(status)}</button>`).join('')}</div></section>`).join(''):'<p>Salus has not selected any records for this scope yet.</p>'}<p class="subtle">For sensitive records or annexes, ask Salus for a separate protected handling route.</p>`;
            intake.items.forEach(item=>{
              const section=intakePanel.querySelector(`#intake-status-${Number(item.id)}`)?.closest('section');
              if(!section)return;
              const files=intake.uploads.filter(upload=>Number(upload.intake_request_id)===Number(item.id));
              const form=document.createElement('form');
              form.innerHTML=`<label>Send this requested record (PDF, Office document, CSV, text or image; up to 25 MB each, five per item)<input type="file" name="file" accept=".pdf,.docx,.xlsx,.csv,.txt,.png,.jpg,.jpeg" required></label><button class="btn secondary" type="submit">Upload file</button><div role="status" aria-live="polite"></div>`;
              const list=document.createElement('div');
              list.innerHTML=files.map(upload=>`<p><a href="/api/package-intake-files/${Number(upload.id)}/download">${esc(upload.original_name)}</a> — received</p>`).join('');
              section.append(form,list);
              form.onsubmit=async event=>{
                event.preventDefault();const button=form.querySelector('button'),status=form.querySelector('[role="status"]');
                const selected=form.elements.namedItem('file').files?.[0];if(!selected)return;
                button.disabled=true;status.textContent='Checking and saving the file…';
                try{
                  const body=new FormData();body.append('file',selected);
                  const response=await fetch(`/api/assessments/${activeAssessmentId}/package-intake/${Number(item.id)}/files`,{method:'POST',headers:authHeaders(),body});
                  if(!response.ok)throw new Error('Upload failed');
                  const saved=await response.json();
                  intakePanel.querySelector(`#intake-status-${Number(item.id)}`).textContent='Provided';
                  if(!list.querySelector(`a[href="/api/package-intake-files/${Number(saved.id)}/download"]`)){
                    list.insertAdjacentHTML('beforeend',`<p><a href="/api/package-intake-files/${Number(saved.id)}/download">${esc(saved.original_name)}</a> — received</p>`);
                  }
                  form.reset();status.textContent='File received. Salus will review its relevance and handling.';
                }catch(error){status.textContent='The file was not saved. Check its type and size, or contact Salus for protected handling.';}
                finally{button.disabled=false;}
              };
            });
            intakePanel.querySelectorAll('button[data-intake-id]').forEach(button=>button.onclick=async()=>{
              button.disabled=true;
              try{
                const result=await api(`/api/assessments/${activeAssessmentId}/package-intake/${Number(button.dataset.intakeId)}`,{method:'PATCH',body:JSON.stringify({status:button.dataset.intakeStatus})});
                intakePanel.querySelector(`#intake-status-${Number(result.item_id)}`).textContent=result.status;
              }catch(error){button.closest('section').insertAdjacentHTML('beforeend','<p role="alert">This response was not saved. Please try again or contact Salus.</p>');}
              finally{button.disabled=false;}
            });
          }catch(error){intakePanel.innerHTML='<h2>Your Level 1 records request</h2><p>The records list is temporarily unavailable. Please contact Salus before sending files.</p>';}
          }
        }
        }
      }catch(error){quotePanel.innerHTML='<h2>Your package quote</h2><p>No current approved quote is available for this selected assessment. Salus must confirm the scope and capacity before offering one.</p>';}
    }
    if(systemMode.package_handoff_candidate_available && ['Assessment Director','System Administrator'].includes(currentRole) && rows.some(r=>r.id===activeAssessmentId)){
      const releasePanel=document.createElement('div'); releasePanel.className='card'; releasePanel.style.marginTop='16px';
      releasePanel.innerHTML='<h2>Four-report release check</h2><p>Checking the current package reports and open approval steps…</p>';
      $('#content').appendChild(releasePanel);
      try{
        const readiness=await api(`/api/assessments/${activeAssessmentId}/package-release-readiness`);
        releasePanel.innerHTML=`<h2>Four-report release check</h2><p><strong>${esc(readiness.status)}</strong> — These checks show what Salus still needs before any report can be issued. A saved draft or comparison is not approval.</p><p>${readiness.reports.length?readiness.reports.map(item=>`${esc(item.product)} version ${Number(item.version_no)} (${esc(item.status)})`).join(' · '):'No working package reports are registered yet.'}</p><ul>${readiness.blockers.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`;
      }catch(error){releasePanel.innerHTML='<h2>Four-report release check</h2><p>Release status is unavailable for this selected assessment. No report should be treated as issued from this screen.</p>';}
      const reviewPanel=document.createElement('div'); reviewPanel.className='card'; reviewPanel.style.marginTop='16px';
      reviewPanel.innerHTML='<h2>Protection Advisor receipts awaiting Salus review</h2><p>Compare the prospect receipt with the Member request. Record three separate reasons for a match. This review only prepares a quote; it does not approve a purchase.</p><div id="advisor-review-list">Loading claimed receipts…</div><div id="advisor-review-detail"></div>';
      $('#content').appendChild(reviewPanel);
      try{
        const claimed=await api(`/api/assessments/${activeAssessmentId}/advisor-package-handoffs`);
        const list=reviewPanel.querySelector('#advisor-review-list');
        list.innerHTML=claimed.handoffs.length?claimed.handoffs.map((h,i)=>`<div class="row-actions"><span>${esc(h.receipt_id)} · revision ${Number(h.revision_no)} · ${esc(h.status)}</span><button class="btn secondary" type="button" data-handoff-index="${i}">Compare</button></div>`).join(''):'<p>No claimed receipts for this assessment.</p>';
        list.querySelectorAll('button[data-handoff-index]').forEach(button=>button.onclick=()=>showAdvisorHandoffReview(activeAssessmentId,claimed.handoffs[Number(button.dataset.handoffIndex)],reviewPanel));
      }catch(error){reviewPanel.querySelector('#advisor-review-list').textContent='Claimed receipts are unavailable. Please contact Salus support.';}
      const intakeReview=document.createElement('div'); intakeReview.className='card'; intakeReview.style.marginTop='16px';
      $('#content').appendChild(intakeReview);
      try{
        const intake=await api(`/api/assessments/${activeAssessmentId}/package-intake`);
        const requested=new Set(intake.items.map(item=>item.item_key));
        intakeReview.innerHTML=`<h2>Tailor the Level 1 records request</h2><p>Select only records that could change this Member's agreed decision. The Member can identify missing records or upload a requested non-sensitive file after authorization. Existing requests will not be duplicated.</p><form id="package-intake-select">${intake.catalog.map(item=>`<label class="advisor-confirm" data-guidance-enhanced="true"><input type="checkbox" name="item_key" value="${esc(item.key)}" ${requested.has(item.key)?'disabled':''}><span><strong>${esc(item.title)}</strong> — ${esc(item.decision_use)}${requested.has(item.key)?' (already requested)':''}</span></label>`).join('')}<label data-guidance-enhanced="true">Why these items matter for this agreed boundary<textarea name="request_reason" minlength="12" maxlength="1000" required></textarea></label><div class="form-actions"><button class="btn">Send selected request</button></div></form><div id="package-intake-result" role="status" aria-live="polite"></div>`;
        intakeReview.querySelector('form').onsubmit=async event=>{
          event.preventDefault();const form=event.currentTarget,selected=[...form.querySelectorAll('input[name="item_key"]:checked')].map(input=>input.value),status=intakeReview.querySelector('#package-intake-result');
          if(!selected.length){status.textContent='Select at least one new item.';return;}
          const button=form.querySelector('button');button.disabled=true;
          try{await api(`/api/assessments/${activeAssessmentId}/package-intake`,{method:'POST',body:JSON.stringify({item_keys:selected,request_reason:form.elements.namedItem('request_reason').value.trim()})});status.textContent='Selected records requested for this authorized package.';selected.forEach(key=>{const input=[...form.querySelectorAll('input[name="item_key"]')].find(item=>item.value===key);if(input)input.disabled=true;});form.reset();}
          catch(error){status.textContent='The request was not saved. Check the selected scope and try again.';}
          finally{button.disabled=false;}
        };
      }catch(error){intakeReview.innerHTML='<h2>Level 1 records request</h2><p>Records may be requested after the Member has authorized this package and its scope is current.</p>';}
    }
  }else{
  $('#content').innerHTML=`<div class="split"><div class="card">${editor}</div><div><div class="section-title"><h2>${c.title} Register</h2><span class="subtle">${rows.length} records</span></div>${entityTable(key,c,rows)}</div></div>`;
  }
  const form=$('#entity-form');
  if(form&&key==='capabilities'){const mt=form.elements.measurement_type,cmp=form.elements.comparator;if(mt&&cmp){const sync=()=>{if(mt.value==='Binary')cmp.value='=';};mt.onchange=sync;sync();}}
  if(form) form.onsubmit=async e=>{e.preventDefault(); const data={}; new FormData(e.target).forEach((v,k)=>{const field=c.fields.find(f=>f[0]===k); const type=field?.[2]; if(v===''){if(type==='relation')data[k]=null;return;} data[k]=(type==='number'||type==='relation'||k==='requested_package_level')?Number(v):v}); if(!edit&&key!=='assessments')data.assessment_id=activeAssessmentId; if(!edit&&key==='decisions')data.authority=currentUser; if(edit) await api(`/api/${key}/${edit.id}`,{method:'PUT',body:JSON.stringify(data)}); else {const created=await api('/api/'+key,{method:'POST',body:JSON.stringify(data)}); if(key==='assessments'){activeAssessmentId=created.id;localStorage.setItem('salus_assessment_id',String(created.id));await renderAssessmentSelector();}} editingRecord=null; render();};
}
async function showAdvisorHandoffReview(assessmentId,handoff,panel){
  const detail=panel.querySelector('#advisor-review-detail'),base=`/api/assessments/${assessmentId}/advisor-package-handoff/${encodeURIComponent(handoff.handoff_key)}`;
  detail.textContent='Loading the comparison…';
  try{
    const packet=await api(`${base}/review-packet`),prospect=packet.prospect_receipt,member=packet.member_request;
    detail.innerHTML=`<h3>Compare receipt ${esc(prospect.id)} · revision ${Number(prospect.revision)}</h3><p><a href="${base}/receipt.pdf" target="_blank" rel="noopener">Download and inspect the saved receipt PDF</a> and confirm its revision and content before recording a review.</p><div class="split"><div><h4>Prospect stated</h4><p>Organization: ${esc(prospect.organization)}<br>Boundary: ${esc(prospect.requested_boundary)}<br>Location: ${esc(prospect.requested_location)}<br>Possible path: ${esc(prospect.possible_path)}</p></div><div><h4>Member requested</h4><p>Organization: ${esc(member.organization)}<br>Covered operation: ${esc(member.covered_operation)}<br>Exclusions: ${esc(member.exclusions)}<br>Level and band: ${esc(member.level)}${esc(member.band)}</p></div></div><p>${esc(packet.review_limit)}</p>${handoff.status==='Claimed'?`<form id="advisor-handoff-review"><label data-guidance-enhanced="true">How did you verify the organization match?<textarea name="organization_match_basis" minlength="12" maxlength="1000" required></textarea></label><label data-guidance-enhanced="true">How did you verify the covered boundary and exclusions?<textarea name="covered_boundary_basis" minlength="12" maxlength="1000" required></textarea></label><label data-guidance-enhanced="true">How did you verify the Member decision role?<textarea name="decision_role_basis" minlength="12" maxlength="1000" required></textarea></label><label class="advisor-confirm" data-guidance-enhanced="true"><input name="confirm_exact_receipt" type="checkbox" required> I downloaded and inspected the saved PDF and compared this exact receipt revision.</label><div class="form-actions"><button class="btn">Record review for quote preparation</button></div></form>`:'<p>This receipt has already been reviewed for quote preparation.</p>'}<div id="advisor-review-result" role="status" aria-live="polite"></div>`;
    const form=detail.querySelector('#advisor-handoff-review');
    if(form)form.onsubmit=async event=>{
      event.preventDefault(); const button=form.querySelector('button'),status=detail.querySelector('#advisor-review-result'); button.disabled=true;
      try{
        const values=Object.fromEntries(new FormData(form));
        const result=await api(`${base}/review`,{method:'POST',body:JSON.stringify({assessment_version:Number(member.assessment_version),organization_match_basis:values.organization_match_basis,covered_boundary_basis:values.covered_boundary_basis,decision_role_basis:values.decision_role_basis,confirm_exact_receipt:true})});
        form.remove(); status.textContent=result.status;
      }catch(error){status.textContent='Review could not be recorded. Reopen the current receipt and assessment, then try again.';button.disabled=false;}
    };
  }catch(error){detail.textContent='The comparison is unavailable or has changed. Refresh the assessment and contact Salus support if needed.';}
}
function formHtml(fields,record={},relations={}){return `<div class="form-grid">${fields.map(f=>{const [name,label,type,opt]=f; const wide=type==='textarea'?'wide':''; const val=record[name]??''; if(type==='select'){const accessField=['classification','sensitivity'].includes(name);return `<label class="${wide}">${label}<select name="${name}">${opt.map(o=>`<option value="${esc(o)}" ${String(o)===String(val)?'selected':''}>${esc(accessField&&o==='Restricted'?'Limited Access — Only people working this matter':o)}</option>`).join('')}</select>${accessField?'<span class="field-help">Standard uses normal access. Sensitive is need-to-know. Highly Sensitive is named people only. Sharing with a Protected Member is a separate decision.</span>':''}</label>`;} if(type==='relation'){const cfg=opt||{};const rows=relations[name]||[];const empty=cfg.required?'':`<option value="">None / Not linked</option>`;const options=rows.map(r=>`<option value="${r.id}" ${String(r.id)===String(val)?'selected':''}>${esc(relationLabel(r,cfg))}</option>`).join('');return `<label>${label}<select name="${name}" ${cfg.required?'required':''}>${empty}${options||'<option value="">No eligible records available</option>'}</select></label>`;} if(type==='textarea') return `<label class="${wide}">${label}<textarea name="${name}" ${opt===1?'required':''}>${esc(val)}</textarea></label>`; return `<label class="${wide}">${label}<input name="${name}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(val)}" ${opt===1?'required':''}></label>`}).join('')}</div>`}
function entityTable(key,c,rows){
  let headers=c.cols.map(x=>x.replaceAll('_',' ')); headers.push('');
  return table(headers,rows.map(r=>[...c.cols.map(col=>{let v=r[col]; if(col==='requested_package_path'){const n=Number(r.requested_package_level||0),b=r.requested_scope_band||'',x=r.requested_access_variant||'';return esc(n&&b?'Requested Level '+n+b+(x?' '+x:''):'Not scoped yet')}; if(col==='status'||col==='severity'||col==='confidence'||col==='verification_status'||col==='lifecycle_status'||col==='review_lifecycle_status'||col==='reassessment_lifecycle_status'||col==='decision_type') return badge(v); if(col.includes('cost')||col==='funding_authorized') return fmtMoney(v); if(col==='priority_score') return Number(v||0).toFixed(1); if(col==='attainment_percent') return Number(v||0).toFixed(1)+'%'; if(col==='target_status') return badge(v); if(col==='scope_locked') return v?'Locked':'Open'; return esc(v)}),
    key==='decisions'?`<div class="row-actions"><span class="subtle">Immutable</span><button class="btn secondary" onclick="reviewExecutiveDecision(${r.id},'${esc(r.review_date||'')}')">Controlled Review</button></div>`:
    key==='assessments'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('assessments',${r.id})">Edit</button><button class="btn secondary" onclick="reviewAssessmentReassessment(${r.id},'${esc(r.reassessment_date||'')}')">Reassessment Review</button></div>`:
    key==='evidence'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('evidence',${r.id})">Edit</button><button class="btn secondary" onclick="reviewEvidenceLifecycle(${r.id},'${esc(r.valid_until||'')}')">Lifecycle Review</button><button class="btn secondary" onclick="del('evidence',${r.id})">Delete</button></div>`:
    key==='gaps'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('gaps',${r.id})">Edit</button><button class="btn secondary" onclick="transitionGap(${r.id},'${esc(r.status)}')">Change State</button></div>`:
    key==='improvements'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('improvements',${r.id})">Edit</button><button class="btn secondary" onclick="transitionImprovement(${r.id},'${esc(r.status)}')">Change State</button></div>`:
    key==='accepted_risks'?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('accepted_risks',${r.id})">Update Record</button>${r.status==='Active'||r.status==='Under Review'?`<button class="btn secondary" onclick="transitionAcceptedRisk(${r.id},'${esc(r.status)}')">Change State</button><button class="btn secondary" onclick="reviewAcceptedRisk(${r.id},'${esc(r.review_date||'')}')">Controlled Review</button>`:'<span class="subtle">Terminal record</span>'}</div>`:
    c.allowDelete===false?`<div class="row-actions"><button class="btn secondary" onclick="editEntity('${key}',${r.id})">Review / Update</button></div>`:`<div class="row-actions"><button class="btn secondary" onclick="editEntity('${key}',${r.id})">Edit</button><button class="btn secondary" onclick="del('${key}',${r.id})">Delete</button></div>`]));
}
function editEntity(key,id){editingRecord={key,id}; entityView(key)}
function cancelEdit(){editingRecord=null; render()}
async function del(k,id){if(!confirm('Delete this record? This action is audit logged.')) return; await api(`/api/${k}/${id}`,{method:'DELETE'}); editingRecord=null; render();}
async function reviewEvidenceLifecycle(id,currentValidUntil=''){const validUntil=prompt('New valid-until date (YYYY-MM-DD). This controlled review restores lifecycle status to Current.',currentValidUntil||'');if(!validUntil)return;const note=prompt('Document the lifecycle review basis / validation performed:','');if(!note)return;await api(`/api/evidence/${id}/lifecycle-review`,{method:'POST',body:JSON.stringify({valid_until:validUntil,review_note:note})});render();}
