async function trace(){const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">Create an assessment first.</div>';return} const id=a.id; const d=await api('/api/trace/'+id); let html=`<div class="notice"><strong>${esc(d.assessment.name)}</strong><br>${esc(d.assessment.mission)}</div><div class="card tree"><ul>`; for(const t of d.threats){const ov=t.active_risk_override;html+=`<li><span class="trace-node"><strong>Threat:</strong> ${esc(t.name)} · Raw risk ${t.risk_raw}${ov?` · Professional ${esc(ov.assigned_band)} ${ov.assigned_score} by ${esc(ov.authority)}`:''}</span>${t.risk_overrides?.length?`<ul><li><span class="trace-node"><strong>Professional Override History:</strong> ${t.risk_overrides.length} record(s); calculated risk remains separately preserved</span></li></ul>`:''}<ul>`; for(const s of t.scenarios){html+=`<li><span class="trace-node"><strong>Scenario:</strong> ${esc(s.title)}</span><ul>`; for(const c of s.capabilities){html+=`<li><span class="trace-node"><strong>Capability:</strong> ${esc(c.name)} · ${esc(c.comparator)} ${esc(c.required_standard)} ${esc(c.measurement_unit)} · Current ${esc(c.current_performance)} ${esc(c.measurement_unit)} · Attainment ${Number(c.attainment_percent||0).toFixed(1)}%</span><ul>`; for(const g of c.gaps){html+=`<li><span class="trace-node"><strong>Gap:</strong> ${esc(g.description)} · ${esc(g.severity)}</span><ul>`; for(const i of g.improvements){html+=`<li><span class="trace-node"><strong>Improvement:</strong> ${esc(i.title)} · ${fmtMoney(i.initial_cost)} · ${esc(i.status)} · Validation ${esc(i.validation_status||'Pending')}</span><ul>`; for(const dec of i.decisions){html+=`<li><span class="trace-node"><strong>Decision:</strong> ${esc(dec.decision_type)} by ${esc(dec.authority)}</span>${dec.accepted_risk?`<ul><li><span class="trace-node"><strong>Accepted Risk:</strong> ${esc(dec.accepted_risk.title)} · ${esc(dec.accepted_risk.status)} · Review ${esc(dec.accepted_risk.review_date)}</span></li></ul>`:''}</li>`} html+='</ul></li>'} html+='</ul></li>'} html+='</ul></li>'} html+='</ul></li>'} html+='</ul></li>'} html+='</ul></div>'; $('#content').innerHTML=html;}

async function implementation(){
  const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">Create an assessment first.</div>';return}
  const [items,decisions,evidence]=await Promise.all([api('/api/improvements?assessment_id='+a.id),api('/api/decisions?assessment_id='+a.id),api('/api/evidence?assessment_id='+a.id)]);
  const decisionByImprovement={}; decisions.forEach(d=>{if(d.improvement_id) decisionByImprovement[d.improvement_id]=d});
  const rows=items.map(i=>{const d=decisionByImprovement[i.id]; const action=i.status==='Complete'?`<button class="btn secondary" onclick="beginImprovementValidation(${i.id})">${i.validation_status==='Pending'?'Validate':'Revalidate'}</button>`:'<span class="subtle">Complete first</span>'; return [i.id,esc(i.title),badge(i.status),badge(i.validation_status||'Pending'),esc(i.owner||''),fmtMoney(i.initial_cost),`<strong>${Number(i.priority_score).toFixed(1)}</strong>`,d?badge(d.decision_type):'<span class="subtle">Pending</span>',action]});
  let panel='';
  if(validatingImprovementId){
    const imp=items.find(x=>x.id===validatingImprovementId); const verified=evidence.filter(x=>x.verification_status==='Verified'&&x.lifecycle_status==='Current');
    panel=`<div class="card" style="margin-bottom:16px"><div class="section-title"><h2>Validate Improvement — ${esc(imp?.title||'')}</h2><button class="btn secondary" onclick="cancelImprovementValidation()">Cancel</button></div><p class="subtle">Validation is a governed action. It requires Verified evidence whose lifecycle is Current. Completion or approval alone never earns validated residual-risk credit.</p>${verified.length?`<form id="validation-form"><label>Verified Evidence<select name="evidence_id" required>${verified.map(e=>`<option value="${e.id}">#${e.id} — ${esc(e.title)}</option>`).join('')}</select></label><label>Validation Status<select name="validation_status"><option>Validated</option><option>Partially Validated</option><option>Failed</option></select></label><label>Validated Effectiveness (%)<input type="number" min="0" max="100" step="0.1" name="validated_effectiveness_percent" value="100" required></label><label>Validation Outcome<textarea name="validation_outcome" required></textarea></label><div class="form-actions"><button class="btn">Record Validation</button></div></form>`:'<div class="notice"><strong>No Verified evidence is available.</strong><br>Verify a Current evidence record before validating this improvement.</div>'}</div>`;
  }
  $('#content').innerHTML=`${panel}<div class="notice"><strong>Implementation discipline:</strong> marking an improvement Complete does not reduce validated risk. Completion opens a reassessment trigger; validated residual risk changes only after a controlled validation cites Verified evidence.</div>${table(['ID','Improvement','Status','Validation','Owner','Initial Cost','Priority','Decision','Validation Action'],rows)}`;
  const form=$('#validation-form'); if(form) form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const status=fd.get('validation_status');let effect=Number(fd.get('validated_effectiveness_percent'));if(status==='Failed')effect=0;await api(`/api/improvements/${validatingImprovementId}/validate`,{method:'POST',body:JSON.stringify({evidence_id:Number(fd.get('evidence_id')),validation_status:status,validated_effectiveness_percent:effect,validation_outcome:fd.get('validation_outcome')})});validatingImprovementId=null;render();};
}
function beginImprovementValidation(id){validatingImprovementId=id;render();}
function cancelImprovementValidation(){validatingImprovementId=null;render();}

async function reports(){
  const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">No assessment available.</div>';return}
  const canCreateReport=!isProtectedMember()&&(accessState?.permissions||[]).includes('write');
  const canAdvanceReport=status=>{
    const next={Draft:'Reviewed',Reviewed:'Approved',Approved:'Released'}[status];
    const roles={Reviewed:['Assessment Director','Lead Assessor'],Approved:['System Administrator','Assessment Director','Client Executive'],Released:['System Administrator','Assessment Director']};
    return next&&(roles[next]||[]).includes(currentRole);
  };
  const id=a.id; const [d, gaps, improvements, decisions, accepted, overrides, risks, priorities, versions] = await Promise.all([api('/api/trace/'+id),api('/api/gaps?assessment_id='+id),api('/api/improvements?assessment_id='+id),api('/api/decisions?assessment_id='+id),api('/api/accepted_risks?assessment_id='+id),api('/api/risk_overrides?assessment_id='+id),api('/api/risk/'+id),api('/api/priorities/'+id),api('/api/reports/'+id)]);
  let threatCount=d.threats.length, scenarioCount=0, capabilityCount=0, capabilityGap=0, rawRisks=[];
  d.threats.forEach(t=>{rawRisks.push(t.risk_raw); scenarioCount+=t.scenarios.length; t.scenarios.forEach(s=>{capabilityCount+=s.capabilities.length; s.capabilities.forEach(c=>capabilityGap+=c.gap)})});
  const high=gaps.filter(g=>['High','Critical'].includes(g.severity)).length;
  const proposed=improvements.reduce((a,i)=>a+Number(i.initial_cost||0),0);
  const authorized=decisions.reduce((a,i)=>a+Number(i.funding_authorized||0),0);
  const avgGap=capabilityCount?capabilityGap/capabilityCount:0;
  const reportRows=versions.map(v=>[v.id,'v'+v.assessment_version,badge(v.status),`<code>${esc(v.snapshot_sha256.slice(0,16))}…</code>`,esc(v.created_at),esc(v.released_by||v.approved_by||v.reviewed_by||v.created_by),`<div class="row-actions"><button class="btn secondary" onclick="openReportSnapshot(${v.id})">Open Snapshot</button>${canAdvanceReport(v.status)?`<button class="btn" onclick="advanceReport(${v.id},'${v.status}')">Advance</button>`:''}</div>`]);
  const primaryAction=canCreateReport?`<button class="btn" onclick="createReportVersion(${id})">Prepare Governed Report</button>`:'';
  $('#content').innerHTML=`
  <div class="card cop-hero"><span>Reports · Review and release</span><h2>Prepare a report for authorized review</h2><p>Use the saved assessment record to prepare an immutable report version. Qualified people retain review, approval, and release authority.</p></div>
  <section class="page-section">
    <div class="stage-heading"><span>1</span><div><h2>Needs Your Attention</h2><p>Prepare a current version or advance only the report versions you are authorized to review.</p></div>${primaryAction}</div>
    ${table(['ID','Assessment Version','Status','SHA-256','Created','Authority','Next step'],reportRows)}
  </section>
  <section class="page-section">
    <div class="stage-heading"><span>2</span><div><h2>Current Work</h2><p>Confirm the assessment context and supporting measures before review or release.</p></div></div>
    <div class="card"><h3>${esc(d.assessment.name)}</h3><p class="subtle">${esc(d.assessment.organization)} · ${esc(d.assessment.assessment_type)} · Status: ${esc(d.assessment.status)} · Version ${d.assessment.version}</p><p><strong>Mission:</strong> ${esc(d.assessment.mission)}</p><p><strong>Purpose:</strong> ${esc(d.assessment.purpose)}</p></div>
    <div class="grid stats" style="margin-top:16px">${metric('Threats / Hazards',threatCount)}${metric('Scenarios',scenarioCount)}${metric('Capabilities',capabilityCount)}${metric('High / Critical Gaps',high)}${metric('Avg Capability Gap',avgGap.toFixed(1)+' pts')}${metric('Proposed Initial Cost',fmtMoney(proposed))}${metric('Authorized Funding',fmtMoney(authorized))}${metric('Highest Raw Risk',rawRisks.length?Math.max(...rawRisks):0)}</div>
  </section>
  <details class="card progressive-panel"><summary>Preview and export</summary><p class="subtle">Preview and export do not approve or release a governed report version.</p><div class="row-actions"><button class="btn secondary" onclick="openExecutiveReport(${id})">Live Preview</button><button class="btn secondary" onclick="downloadExecutiveCsv(${id})">Download Executive CSV</button><button class="btn secondary" onclick="downloadAssessmentExport(${id})">Download Assessment Package</button></div></details>
  <details class="card progressive-panel"><summary>Supporting assessment detail</summary>
    <div class="section-title"><h2>Risk Outlook</h2></div>${table(['Threat / Hazard','Inherent','Current','Professional Assigned','Predicted Residual','Validated Residual','Confidence'],risks.map(r=>[esc(r.name),`${badge(r.inherent_band)} ${r.inherent_score}`,`${badge(r.current_band)} ${r.current_score}`,r.professional_override?`${badge(r.assigned_risk_band)} ${r.assigned_risk_score}`:'—',`${badge(r.predicted_residual_band)} ${r.predicted_residual_score}`,`${badge(r.validated_residual_band)} ${r.validated_residual_score}`,badge(r.confidence)]))}
    <div class="section-title"><h2>Top Improvement Priorities</h2></div>${table(['Priority','Improvement','Gap Severity','Cost','Status'],priorities.slice(0,10).map(r=>[`<strong>${r.priority_score}</strong>`,esc(r.title),badge(r.gap_severity),fmtMoney(r.initial_cost),badge(r.status)]))}
    <div class="section-title"><h2>Executive Decisions</h2></div>${table(['Decision','Authority','Funding','Rationale','Review Date'],decisions.map(x=>[badge(x.decision_type),esc(x.authority),fmtMoney(x.funding_authorized),esc(x.rationale),esc(x.review_date)]))}
    <div class="section-title"><h2>Accepted Risk Register</h2></div>${table(['Status','Risk','Authority','Residual Exposure','Owner','Review Date'],accepted.map(x=>[badge(x.status),esc(x.title),esc(x.authority),esc(x.residual_exposure),esc(x.owner),esc(x.review_date)]))}
    <div class="section-title"><h2>Professional Risk Override Register</h2></div>${table(['Status','Threat','Calculated','Assigned','Authority','Reason','Review Date'],overrides.map(x=>[badge(x.status),x.threat_id,`${badge(x.calculated_band)} ${x.calculated_score}`,`${badge(x.assigned_band)} ${x.assigned_score}`,esc(x.authority),esc(x.reason),esc(x.review_date)]))}
    <div class="section-title"><h2>Priority Gaps</h2></div>${table(['Severity','Type','Description','Status'],gaps.filter(g=>['High','Critical'].includes(g.severity)).map(g=>[badge(g.severity),esc(g.gap_type),esc(g.description),badge(g.status)]))}
  </details>`;
}
async function createReportVersion(id){await api('/api/reports/'+id,{method:'POST'});render();}
async function advanceReport(id,current){const next={Draft:'Reviewed',Reviewed:'Approved',Approved:'Released'}[current];const reason=prompt(`Document the authority basis for ${next}:`);if(!reason)return;await api(`/api/reports/versions/${id}/transition`,{method:'POST',body:JSON.stringify({status:next,reason})});render();}
