async function configuration(){
  const a=await getActiveAssessment();
  const [profiles,industryConfigs,w]=await Promise.all([api('/api/industry-profiles'),api('/api/industry-configurations'),a?api('/api/weights/'+a.id):Promise.resolve(null)]);
  if(isProtectedMember()){
    $('#content').innerHTML=`<div class="section-title"><h2>Organization profiles</h2><span class="subtle">Published guidance selected for your organization</span></div>${table(['Industry','Profile','Version','Summary','Status'],industryConfigs.map(x=>[esc(x.industry_code_snapshot),esc(x.profile_name_snapshot),esc(x.profile_version_snapshot),esc(x.member_summary_snapshot),badge(x.status)]))}<div class="notice" style="margin-top:16px">Industry guidance is advisory context. It does not establish compliance, verified evidence, professional authority, or an operational decision.</div>`;return;
  }
  const canGovern=['System Administrator','Assessment Director','Program Owner'].includes(currentRole);
  const roles=[['System Administrator','Read, write, decide, administer'],['Assessment Director','Read, write, decide'],['Lead Assessor','Read, write'],['SME Assessor','Read, write'],['Client Executive','Read, decide'],['Program Owner','Read, write'],['Contributor','Read, write'],['Auditor','Read only']];
  const profileRows=profiles.map(p=>{const action={Draft:'Submit','In Review':'Review',Reviewed:'Approve',Approved:'Publish'}[p.status];const selected=industryConfigs.some(c=>c.profile_id===p.id&&c.status==='Active');return [esc(p.industry_code),`${esc(p.name)}<br><span class="subtle">${esc(p.profile_key)} · v${p.version_no}</span>`,esc(p.member_summary),badge(p.status),selected?badge('Selected'):(p.status==='Published'?'<span class="subtle">Available</span>':''),canGovern?`${action?`<button class="btn" onclick="transitionIndustryProfile(${p.id},'${action}')">${action}</button>`:''} ${p.status==='Published'&&!selected?`<button class="btn" onclick="selectIndustryProfile(${p.id})">Select</button>`:''} ${['Published','Retired','Superseded'].includes(p.status)?`<button class="btn secondary" onclick="reviseIndustryProfile(${p.id})">Revise</button>`:''} ${p.status==='Published'?`<button class="btn secondary" onclick="transitionIndustryProfile(${p.id},'Retire')">Retire</button>`:''}`:'']});
  const industryForm=canGovern?`<div class="card"><div class="section-title"><h2>Define industry profile</h2></div><p class="subtle">Reusable guidance remains advisory. Independent review, approval, publication, and tenant selection are required before it can be applied.</p><form id="industry-form"><label>Industry family<select name="industry_code"><option value="government-public-safety">Government / public safety</option><option value="critical-infrastructure-energy">Critical infrastructure / energy</option><option value="aviation-transportation-logistics">Aviation / transportation / logistics</option><option value="healthcare-ems-public-health">Healthcare / EMS / public health</option><option value="education-faith-community">Education / faith / community</option><option value="hospitality-events-complex-venues">Hospitality / events / complex venues</option></select></label><label>Profile name<input name="name" required></label><label>Member summary<textarea name="member_summary" required></textarea></label><label>Controlled rationale<textarea name="internal_rationale" required></textarea></label><label>Preferred terminology<input name="terminology" required></label><label>Capability guidance<input name="capability" required></label><label>Scenario guidance<input name="scenario" required></label><label>Regulatory reference label<input name="regulatory" required></label><label>SalOPS service default<input name="service_default" required></label><div class="form-actions"><button class="btn">Create draft profile</button></div></form></div>`:'';
  const weights=a?`<div class="card"><div class="section-title"><h2>Consequence weights</h2></div><p class="subtle">Weights influence scenario consequence. A value of 1.0 is neutral.</p><form id="weights-form">${['life_safety','mission','operations','financial','legal_regulatory','reputation','recovery'].map(k=>`<label>${k.replaceAll('_',' ')}<input type="number" step="0.1" min="0" max="10" name="${k}" value="${esc(w[k])}"></label>`).join('')}<div class="form-actions"><button class="btn">Save weights</button></div></form></div>`:'<div class="notice">Create an assessment to configure consequence weights.</div>';
  $('#content').innerHTML=`<div class="split">${industryForm}<div><div class="section-title"><h2>Industry profile governance</h2><span class="subtle">Versioned tenant configuration</span></div>${table(['Industry','Profile','Member summary','Status','Tenant use','Actions'],profileRows)}</div></div><div class="notice" style="margin:16px 0"><strong>Advisory boundary:</strong> Profile defaults never create verified evidence, intelligence, risk findings, qualifications, compliance conclusions, operational authority, or lifecycle state.</div><div class="two-col grid">${weights}<div><div class="section-title"><h2>Access roles</h2></div>${table(['Role','Permissions'],roles)}</div></div>`;
  const industryFormElement=$('#industry-form');if(industryFormElement)industryFormElement.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const item=(item_type,item_key,field)=>({item_type,item_key,member_label:fd.get(field),member_guidance:fd.get(field),internal_definition:fd.get(field),reference_metadata:item_type==='Regulatory Reference'?'Reference metadata only; validation remains separate.':'',default_payload:item_type==='Service Default'?{advisory:fd.get(field)}:{},member_visible:true,sort_order:10});await api('/api/industry-profiles',{method:'POST',body:JSON.stringify({industry_code:fd.get('industry_code'),name:fd.get('name'),member_summary:fd.get('member_summary'),internal_rationale:fd.get('internal_rationale'),items:[item('Terminology','preferred-terminology','terminology'),item('Capability','capability-guidance','capability'),item('Scenario','scenario-guidance','scenario'),item('Regulatory Reference','regulatory-reference','regulatory'),item('Service Default','service-default','service_default')]})});render();};
  const weightsForm=$('#weights-form');if(weightsForm)weightsForm.onsubmit=async e=>{e.preventDefault();const d={};new FormData(e.target).forEach((v,k)=>d[k]=Number(v));await api('/api/weights/'+a.id,{method:'PUT',body:JSON.stringify(d)});render()};
}
async function transitionIndustryProfile(id,action){const reason=prompt(`Document the ${action.toLowerCase()} authority and basis:`);if(!reason)return;await api(`/api/industry-profiles/${id}/transition`,{method:'POST',body:JSON.stringify({action,reason})});render();}
async function selectIndustryProfile(id){if(!confirm('Select this exact published profile version for new tenant work? Existing records keep their snapshots.'))return;await api('/api/industry-configurations',{method:'POST',body:JSON.stringify({profile_id:id})});render();}
async function reviseIndustryProfile(id){const profiles=await api('/api/industry-profiles');const p=profiles.find(x=>x.id===id);if(!p)return;const name=prompt('Revised profile name:',p.name);if(!name)return;const member_summary=prompt('Revised member summary:',p.member_summary);if(!member_summary)return;const internal_rationale=prompt('Revised controlled rationale:',p.internal_rationale);if(!internal_rationale)return;const items=p.items.map(({item_type,item_key,member_label,member_guidance,internal_definition,reference_metadata,default_payload,member_visible,sort_order})=>({item_type,item_key,member_label,member_guidance,internal_definition,reference_metadata,default_payload:default_payload||{},member_visible:!!member_visible,sort_order}));await api(`/api/industry-profiles/${id}/revise`,{method:'POST',body:JSON.stringify({industry_code:p.industry_code,name,member_summary,internal_rationale,items})});render();}

async function salintel(){
  const [rows,observations]=await Promise.all([api('/api/salintel/findings'),api('/api/observations')]);
  if(isProtectedMember()){
    const canSubmit=(accessState?.permissions||[]).includes('write');
    const form=canSubmit?`<div class="card"><div class="section-title"><h2>Report an observation or concern</h2></div><div class="notice"><strong>Immediate danger?</strong> This form is not monitored as an emergency-response channel. Call emergency services or the appropriate emergency number now.</div><p class="subtle">A submission is unverified source information. It does not automatically become intelligence, evidence, a threat finding, or an operational order.</p><form id="observation-form"><div class="form-grid"><label>Title<input name="title" required maxlength="500"></label><label>Observed time<input name="observed_at" type="datetime-local" required></label><label>Location<input name="location" maxlength="1000"></label><label>Reported urgency<select name="reported_urgency"><option>Routine</option><option>Priority</option><option>Urgent</option><option>Critical</option></select></label><label>Contact choice<select name="reporter_choice"><option>Identified</option><option>Confidential Contact</option><option>Anonymous</option></select></label><label>Your name<input name="reporter_name" maxlength="500"></label><label>Contact information<input name="reporter_contact" maxlength="1000"></label><label>Reporting on behalf of<input name="report_on_behalf_of" maxlength="500"></label></div><label>Narrative<textarea name="narrative" required maxlength="12000"></textarea></label><label>Context<textarea name="context" maxlength="4000"></textarea></label><label>Optional attachment<input name="file" type="file"></label><label><input name="emergency_acknowledged" type="checkbox" required> I understand this is not an emergency-response channel.</label><div class="form-actions"><button class="btn">Submit governed observation</button></div></form></div>`:'';
    const memberOpenObservations=observations.filter(x=>x.status!=='Closed');
    const memberClosedObservations=observations.filter(x=>x.status==='Closed');
    $('#content').innerHTML=`${form}<div class="section-title"><h2>Current Work</h2><span class="subtle">Open observation records and acknowledgement status</span></div>${table(['Reference','Observation','Reported urgency','Status','Disposition'],memberOpenObservations.map(x=>[esc(x.record_key),esc(x.title),badge(x.reported_urgency),badge(x.status),esc(x.disposition)]))}<details><summary>Qualified intelligence</summary><p class="subtle">Qualified information released for your organization. Salus personnel preserve source protection and determine what may be disclosed.</p>${table(['Finding','Credibility','Validation','Significance','Status'],rows.map(x=>[esc(x.title),badge(x.credibility),badge(x.validation_status),esc(x.operational_significance),badge(x.status)]))}</details><details><summary>Closed observation history</summary><p class="subtle">Closed records remain available for traceability and review.</p>${table(['Reference','Observation','Reported urgency','Status','Disposition'],memberClosedObservations.map(x=>[esc(x.record_key),esc(x.title),badge(x.reported_urgency),badge(x.status),esc(x.disposition)]))}</details><div class="notice" style="margin-top:16px"><strong>What happens next:</strong> Salus personnel review submitted information before qualification or routing. A submission does not establish a finding, decision, or operational action.</div>`;
    const observationForm=$('#observation-form'); if(observationForm)observationForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const file=fd.get('file');const d={};for(const [k,v] of fd.entries())if(k!=='file')d[k]=v;d.emergency_acknowledged=true;const created=await api('/api/observations',{method:'POST',body:JSON.stringify(d)});if(file&&file.size){const upload=new FormData();upload.append('file',file);await apiForm(`/api/observations/${created.id}/attachments`,upload);}render();};
    return;
  }
  const a=await getActiveAssessment();
  const observationActions=x=>x.status==='Submitted'?`<button class="btn" onclick="acknowledgeObservation(${x.id})">Acknowledge</button>`:x.status==='Acknowledged'?`<button class="btn" onclick="triageObservation(${x.id})">Triage</button>`:x.status==='Triaged'?`<button class="btn" onclick="routeObservation(${x.id})">Route</button> <button class="btn secondary" onclick="closeObservation(${x.id})">Close</button>`:x.status==='Routed'?`<button class="btn secondary" onclick="closeObservation(${x.id})">Close</button>`:'';
  const attentionObservations=observations.filter(x=>x.status!=='Closed');
  const closedObservations=observations.filter(x=>x.status==='Closed');
  $('#content').innerHTML=`<div class="section-title"><h2>Needs Your Attention</h2><span class="subtle">Review and route incoming information. Unverified intake remains separate from qualified intelligence.</span></div>${table(['Reference','Observation','Intake','Reported','Triage','Protection','Status','Assigned','Actions'],attentionObservations.map(x=>[esc(x.record_key),esc(x.title),esc(x.intake_type),badge(x.reported_urgency),badge(x.triage_priority||'Pending'),esc(x.source_protection),badge(x.status),esc(x.assigned_to),observationActions(x)]))}<div class="section-title"><h2>Current Work</h2><span class="subtle">${rows.length} governed intelligence records</span></div><div class="split"><details><summary>Collect a new finding</summary><div class="card"><div class="section-title"><h2>Finding details</h2></div><p class="subtle">Collected information remains unqualified until an authorized Salus professional evaluates relevance, credibility, validation, and operational significance.</p><form id="intel-form"><input type="hidden" name="assessment_id" value="${a?.id||''}"><label>Finding title<input name="title" required></label><label>Source<input name="source" required></label><label>Source locator<input name="source_locator"></label><label>Details<textarea name="details"></textarea></label><div class="form-actions"><button class="btn">Collect finding</button></div></form></div></details><div><div class="section-title"><h2>Intelligence register</h2><span class="subtle">${rows.length} records</span></div>${table(['ID','Finding','Source','Credibility','Validation','Status','Actions'],rows.map(x=>[x.id,esc(x.title),esc(x.source),badge(x.credibility),badge(x.validation_status),badge(x.status),x.status==='Collected'?`<button class="btn secondary" onclick="qualifyIntel(${x.id})">Qualify</button>`:x.status==='Qualified'?`<button class="btn" onclick="sendIntelToThira(${x.id})">Send to SalTHIRA</button>`:'']))}</div></div><details><summary>Closed observation history</summary><p class="subtle">Closed records remain available for traceability and review.</p>${table(['Reference','Observation','Reported urgency','Status','Disposition'],closedObservations.map(x=>[esc(x.record_key),esc(x.title),badge(x.reported_urgency),badge(x.status),esc(x.disposition)]))}</details><div class="notice" style="margin-top:16px"><strong>What happens next:</strong> Authorized personnel qualify relevant information before it can support a SalTHIRA assessment. Routing does not make a human decision or establish operational authority.</div>`;
  $('#intel-form').onsubmit=async e=>{e.preventDefault();const d={};new FormData(e.target).forEach((v,k)=>{if(v!=='')d[k]=k==='assessment_id'?Number(v):v});await api('/api/salintel/findings',{method:'POST',body:JSON.stringify(d)});render();};
}
async function qualifyIntel(id){const significance=prompt('Operational significance:');if(!significance)return;await api(`/api/salintel/findings/${id}/qualify`,{method:'POST',body:JSON.stringify({relevance:'Relevant',credibility:'High',validation_status:'Qualified',operational_significance:significance})});render();}
async function sendIntelToThira(id){await api(`/api/salintel/findings/${id}/send-to-salthira`,{method:'POST'});render();}
async function acknowledgeObservation(id){const reason=prompt('Acknowledgement note:');if(!reason)return;await api(`/api/observations/${id}/acknowledge`,{method:'POST',body:JSON.stringify({reason})});render();}
async function triageObservation(id){const category=prompt('Category: Security Concern, Safety or Hazard, Behavioral Concern, Fraud or Misconduct, Operational, Information, or Other','Security Concern');if(!category)return;const priority=prompt('Triage priority: Routine, Priority, Urgent, or Critical','Priority');if(!priority)return;const assigned_to=prompt('Assign to:');if(!assigned_to)return;const notes=prompt('Triage basis and handling notes:');if(!notes)return;await api(`/api/observations/${id}/triage`,{method:'POST',body:JSON.stringify({category,priority,assigned_to,notes})});render();}
async function routeObservation(id){const target=prompt('Route to: SalINTEL, SalTHIRA, SalOPS, or External Escalation','SalINTEL');if(!target)return;const assessmentRequired=['SalTHIRA','SalOPS'].includes(target);if(assessmentRequired&&!activeAssessmentId){alert('Select or create an assessment before routing this observation to SalTHIRA or SalOPS.');return;}const assessment_id=activeAssessmentId||null;const member_summary=prompt('Member-safe routing summary:');if(!member_summary)return;const reason=prompt('Routing authority and basis:');if(!reason)return;const external_reference=target==='External Escalation'?(prompt('Recorded external reference (SalCAPA will not transmit):')||''):'';if(target==='External Escalation'&&!external_reference)return;await api(`/api/observations/${id}/route`,{method:'POST',body:JSON.stringify({target,assessment_id,member_summary,reason,external_reference})});render();}
async function closeObservation(id){const disposition=prompt('Disposition: Information Only, Not Actionable, Duplicate, Resolved, or Referred','Resolved');if(!disposition)return;const reason=prompt('Closure basis:');if(!reason)return;await api(`/api/observations/${id}/close`,{method:'POST',body:JSON.stringify({disposition,reason})});render();}

async function salops(){
  const [rows,engagements,pillars,catalog,industryProfiles]=await Promise.all([api('/api/salops/requests'),api('/api/salops/engagements'),api('/api/salops/catalog/pillars'),api('/api/salops/catalog/services'),api('/api/industry-profiles')]);
  const a=await getActiveAssessment();
  if(isProtectedMember()){
    const canRequest=(accessState?.permissions||[]).includes('write');
    const requestCard=canRequest&&catalog.length?`<div class="card"><div class="section-title"><h2>Request operational support</h2></div><p class="subtle">Choose an approved service. The published definition and version are preserved with your request; authorization and Salus acceptance remain separate accountable actions.</p><form id="ops-form"><input type="hidden" name="assessment_id" value="${a?.id||''}"><label>Published service<select name="service_catalog_id" required>${catalog.map(s=>`<option value="${s.id}">${esc(s.pillar_name)} — ${esc(s.name)}</option>`).join('')}</select></label><label>Request title<input name="title" required></label><label>Priority<select name="priority"><option>Routine</option><option>Priority</option><option>Urgent</option><option>Critical</option></select></label><label>Description<textarea name="description"></textarea></label><div class="form-actions"><button class="btn">Submit request</button></div></form></div>`:canRequest?'<div class="notice">No published SalOPS services are currently available to request.</div>':'';
    const released=(await Promise.all(engagements.map(x=>api(`/api/salops/engagements/${x.id}/field-reports`)))).flat();
    const financials=await Promise.all(engagements.map(async x=>({engagement:x,data:await api(`/api/salops/engagements/${x.id}/financials`),statements:await api(`/api/salops/engagements/${x.id}/invoice-statements`)})));
    const memberExperts=(await Promise.all(engagements.map(async x=>({engagement:x,assignments:await api(`/api/salops/engagements/${x.id}/experts`)})))).flatMap(x=>x.assignments.map(a=>[esc(x.engagement.title),esc(a.member_display_name_snapshot),esc(a.member_role_title_snapshot),esc(a.member_biography_snapshot),esc(a.member_contact_summary_snapshot),badge(a.status)]));
    const estimateRows=financials.flatMap(({engagement,data})=>data.estimates.map(e=>[esc(engagement.title),esc(e.member_summary),`${esc(e.currency)} ${esc(e.total_amount)}`,badge(e.status),e.status==='Submitted'&&(accessState?.permissions||[]).includes('decide')?`<button class="btn" onclick="advanceEstimate(${e.id},'Approved')">Approve</button> <button class="btn secondary" onclick="advanceEstimate(${e.id},'Rejected')">Reject</button>`:'']));
    const attentionEstimateRows=estimateRows.filter(row=>Boolean(row[4]));
    const actualRows=financials.map(({engagement,data})=>[esc(engagement.title),`${esc(data.currency)} ${esc(data.approved_estimate_total)}`,`${esc(data.currency)} ${esc(data.approved_actual_total)}`,`${esc(data.currency)} ${esc(data.remaining_estimate)}`,data.approved_actual_count]);
    const statementRows=financials.flatMap(({engagement,statements})=>statements.map(s=>[esc(engagement.title),esc(s.statement_number),esc(s.service_summary),`${esc(s.currency)} ${esc(s.billable_total)}`,badge(s.status),`<button class="btn secondary" onclick="openInvoiceReady(${s.id})">View statement</button>`]));
    $('#content').innerHTML=`${requestCard}<div class="section-title"><h2>Needs Your Attention</h2><span class="subtle">Estimate decisions awaiting your authorized review</span></div>${table(['Engagement','Summary','Amount','Status','Actions'],attentionEstimateRows)}<div class="section-title"><h2>Current Work</h2><span class="subtle">${rows.length} governed records</span></div>${table(['Request','Service version','Priority','Status','Result'],rows.map(x=>[esc(x.title),x.service_key_snapshot?`${esc(x.service_name_snapshot)} · v${esc(x.service_version_snapshot)}`:esc(x.source_type),badge(x.priority),badge(x.status),esc(x.result_summary)]))}<div class="section-title"><h2>Active service engagements</h2><span class="subtle">Member-facing status</span></div>${table(['Service','Type','Operating period','Readiness','Status','Update'],engagements.map(x=>[esc(x.title),esc(x.service_type),`${esc(x.planned_start)} — ${esc(x.planned_end)}`,`${x.readiness_summary?.complete||0} complete · ${x.readiness_summary?.exceptions||0} exception · ${x.readiness_summary?.pending||0} pending`,badge(x.status),esc(x.member_status_summary)]))}<details><summary>Available services</summary><div class="section-title"><h2>Available SalOPS services</h2><span class="subtle">Published, member-safe definitions</span></div>${table(['Pillar','Service','Description','Deliverables','Authorization'],catalog.map(s=>[esc(s.pillar_name),esc(s.name),esc(s.member_description),esc(s.default_deliverables),esc(s.authorization_requirements)]))}</details><details><summary>People, financials, statements, and field updates</summary><div class="section-title"><h2>Your assigned experts</h2><span class="subtle">Accepted assignments and approved contact details only</span></div>${table(['Engagement','Expert','Role','Biography','Contact','Status'],memberExperts)}<div class="section-title"><h2>Estimate history</h2><span class="subtle">Member-facing scope and decision record</span></div>${table(['Engagement','Summary','Amount','Status','Actions'],estimateRows)}<div class="section-title"><h2>Financial position</h2><span class="subtle">Approved reimbursable actuals only</span></div>${table(['Engagement','Approved estimate','Approved actuals','Remaining','Approved records'],actualRows)}<div class="section-title"><h2>Released invoice-ready statements</h2><span class="subtle">Approved records; not accounting invoices</span></div>${table(['Engagement','Statement','Service summary','Billable','Status','Actions'],statementRows)}<div class="section-title"><h2>Released field updates</h2><span class="subtle">Approved operational reporting</span></div>${table(['Time','Type','Summary','Status'],released.map(x=>[esc(x.occurred_at),esc(x.report_type),esc(x.member_summary),badge(x.status)]))}</details><div class="notice" style="margin-top:16px"><strong>What happens next:</strong> Submitted requests and estimate decisions move only through authorized Salus and Protected Member review. Nothing on this page creates an invoice or operational authority by itself.</div>`;
  }else{
    const experts=await api('/api/salops/experts');
    const engagementDetails=await Promise.all(engagements.map(async x=>({engagement:x,readiness:await api(`/api/salops/engagements/${x.id}/readiness`),tasks:await api(`/api/salops/engagements/${x.id}/tasks`),reports:await api(`/api/salops/engagements/${x.id}/field-reports`),financials:await api(`/api/salops/engagements/${x.id}/financials`),statements:await api(`/api/salops/engagements/${x.id}/invoice-statements`),assignments:await api(`/api/salops/engagements/${x.id}/experts`),conflicts:await api(`/api/salops/engagements/${x.id}/conflicts`)})));
    const requestRows=rows.map(x=>{const engagement=engagements.find(e=>e.ops_request_id===x.id);const action=x.status==='Requested'?`<button class="btn" onclick="authorizeOps(${x.id})">Authorize</button>`:x.status==='Authorized'&&!engagement?`<button class="btn" onclick="createEngagement(${x.id})">Plan engagement</button>`:'';return [x.id,esc(x.title),esc(x.source_type),badge(x.priority),badge(x.status),esc(x.assigned_to),action]});
    const engagementRows=engagementDetails.map(({engagement:x,readiness,tasks,reports,statements})=>{const next={Planning:'Mobilizing',Mobilizing:'Active',Active:'Demobilizing',Demobilizing:'Closed'}[x.status];const actions=`${next?`<button class="btn" onclick="advanceEngagement(${x.id},'${next}')">${next}</button>`:''} ${['Planning','Mobilizing'].includes(x.status)?`<button class="btn secondary" onclick="createReadiness(${x.id})">Add readiness</button>`:''} ${!['Demobilizing','Closed'].includes(x.status)?`<button class="btn secondary" onclick="discloseExpertConflict(${x.id})">Disclose conflict</button> <button class="btn secondary" onclick="proposeExpertAssignment(${x.id})">Assign expert</button> <button class="btn secondary" onclick="createOpsTask(${x.id},null)">Add unassigned task</button> <button class="btn secondary" onclick="createEstimate(${x.id})">Add estimate</button>`:''} ${['Mobilizing','Active','Demobilizing'].includes(x.status)?`<button class="btn secondary" onclick="createExpense(${x.id})">Add expense</button>`:''} ${['Active','Demobilizing'].includes(x.status)?`<button class="btn secondary" onclick="createFieldReport(${x.id},null)">Field report</button>`:''} ${x.status==='Closed'&&!statements.length?`<button class="btn" onclick="createInvoiceReady(${x.id})">Create invoice-ready statement</button>`:''}`;return [x.id,esc(x.title),esc(x.service_type),badge(x.status),esc(x.operational_lead),`${readiness.filter(r=>r.status==='Pending').length} pending / ${tasks.filter(t=>!['Completed','Cancelled'].includes(t.status)).length} open tasks / ${reports.filter(r=>r.status==='Released').length} released`,actions]});
    const taskRows=engagementDetails.flatMap(({engagement,tasks})=>tasks.map(t=>{const taskActions=[];if(t.status==='Assigned')taskActions.push(`<button class="btn secondary" onclick="advanceOpsTask(${t.id},'In Progress')">Start</button> <button class="btn secondary" onclick="advanceOpsTask(${t.id},'Cancelled')">Cancel</button>`);else if(t.status==='In Progress')taskActions.push(`<button class="btn" onclick="advanceOpsTask(${t.id},'Completed')">Complete</button> <button class="btn secondary" onclick="advanceOpsTask(${t.id},'Cancelled')">Cancel</button>`);if(['Active','Demobilizing'].includes(engagement.status)&&t.status!=='Cancelled')taskActions.push(`<button class="btn secondary" onclick="createFieldReport(${engagement.id},${t.id})">Field report</button>`);return [engagement.id,esc(t.title),esc(t.assigned_to),badge(t.priority),badge(t.status),taskActions.join(' ')]}));
    const reportRows=engagementDetails.flatMap(({engagement,reports})=>reports.map(r=>[engagement.id,esc(r.occurred_at),esc(r.report_type),esc(r.submitted_by),badge(r.status),r.status==='Draft'?`<button class="btn" onclick="releaseFieldReport(${r.id})">Release summary</button>`:'']));
    const readinessRows=engagementDetails.flatMap(({engagement,readiness})=>readiness.map(r=>[engagement.id,esc(r.label),esc(r.member_summary),esc(r.internal_requirement),badge(r.status),r.status==='Pending'?`<button class="btn" onclick="advanceReadiness(${r.id},'Complete')">Complete</button> <button class="btn secondary" onclick="advanceReadiness(${r.id},'Exception')">Exception</button>`:'']));
    const estimateRows=engagementDetails.flatMap(({engagement,financials})=>financials.estimates.map(e=>[engagement.id,esc(e.member_summary),`${esc(e.currency)} ${esc(e.total_amount)}`,badge(e.status),e.lines.map(l=>`${esc(l.category)}: ${esc(l.quantity)} ${esc(l.unit)} × ${esc(l.unit_rate)} = ${esc(l.line_total)}`).join('<br>'),e.status==='Draft'?`<button class="btn" onclick="advanceEstimate(${e.id},'Submitted')">Submit</button>`:e.status==='Submitted'?`<button class="btn" onclick="advanceEstimate(${e.id},'Approved')">Approve</button> <button class="btn secondary" onclick="advanceEstimate(${e.id},'Rejected')">Reject</button>`:'']));
    const expenseRows=engagementDetails.flatMap(({engagement,financials})=>financials.expenses.map(e=>[engagement.id,esc(e.incurred_on),esc(e.category),esc(e.description),`${esc(e.currency)} ${esc(e.amount)}`,badge(e.status),e.status==='Draft'?`<button class="btn" onclick="advanceExpense(${e.id},'Submitted')">Submit</button>`:e.status==='Submitted'?`<button class="btn" onclick="advanceExpense(${e.id},'Approved')">Approve</button> <button class="btn secondary" onclick="advanceExpense(${e.id},'Rejected')">Reject</button>`:'']));
    const varianceRows=engagementDetails.map(({engagement,financials})=>[engagement.id,esc(engagement.title),`${esc(financials.currency)} ${esc(financials.approved_estimate_total)}`,`${esc(financials.currency)} ${esc(financials.approved_actual_total)}`,`${esc(financials.currency)} ${esc(financials.remaining_estimate)}`]);
    const statementRows=engagementDetails.flatMap(({engagement,statements})=>statements.map(s=>[engagement.id,esc(s.statement_number),esc(s.service_summary),`${esc(s.currency)} ${esc(s.billable_total)}`,badge(s.status),s.status==='Draft'?`<button class="btn" onclick="advanceInvoiceReady(${s.id},'Reviewed')">Review</button>`:s.status==='Reviewed'?`<button class="btn" onclick="advanceInvoiceReady(${s.id},'Approved')">Approve</button>`:s.status==='Approved'?`<button class="btn" onclick="advanceInvoiceReady(${s.id},'Released')">Release</button>`:`<button class="btn secondary" onclick="openInvoiceReady(${s.id})">View</button>`]));
    const profileRows=experts.map(p=>[esc(p.profile_key),esc(p.member_display_name),esc(p.expert_actor),esc(p.disciplines),esc(p.jurisdictions),esc(p.regions),badge(p.status),`<button class="btn secondary" onclick="addExpertCredential(${p.id})">Credential</button> <button class="btn secondary" onclick="addExpertAvailability(${p.id})">Availability</button> ${p.status==='Draft'?`<button class="btn" onclick="transitionExpertProfile(${p.id},'Activate')">Activate</button>`:p.status==='Active'?`<button class="btn secondary" onclick="transitionExpertProfile(${p.id},'Deactivate')">Deactivate</button>`:''}`]);
    const credentialRows=experts.flatMap(p=>p.credentials.map(c=>[esc(p.member_display_name),esc(c.credential_type),esc(c.issuer),esc(c.jurisdiction),`${esc(c.effective_on)} — ${esc(c.expires_on||'No expiry')}`,badge(c.status),c.status==='Unverified'?`<button class="btn" onclick="transitionExpertCredential(${c.id},'Verify')">Verify</button> <button class="btn secondary" onclick="transitionExpertCredential(${c.id},'Withdraw')">Withdraw</button>`:c.status==='Verified'?`<button class="btn secondary" onclick="transitionExpertCredential(${c.id},'Withdraw')">Withdraw</button>`:'']));
    const availabilityRows=experts.flatMap(p=>p.availability.map(a=>[esc(p.member_display_name),`${esc(a.available_from)} — ${esc(a.available_until)}`,esc(a.region),badge(a.status),esc(a.recorded_by)]));
    const conflictRows=engagementDetails.flatMap(({engagement,conflicts})=>conflicts.map(c=>{const p=experts.find(x=>x.id===c.profile_id);return [esc(engagement.title),esc(p?.member_display_name||c.profile_id),esc(c.disclosure),badge(c.status),esc(c.reviewed_by),c.status==='Pending'?`<button class="btn" onclick="reviewExpertConflict(${c.id},'Cleared')">Clear</button> <button class="btn secondary" onclick="reviewExpertConflict(${c.id},'Restricted')">Restrict</button>`:'']}));
    const assignmentRows=engagementDetails.flatMap(({engagement,assignments})=>assignments.map(a=>{const p=experts.find(x=>x.id===a.profile_id);const expertActor=p?.expert_actor||'';const taskAction=a.status==='Accepted'?`<button class="btn" onclick="createOpsTask(${engagement.id},${a.id})">Add task</button>`:'';const lifecycleAction=a.status==='Proposed'&&currentUser===expertActor?`<button class="btn" onclick="transitionExpertAssignment(${a.id},'Accept')">Accept</button>`:a.status!=='Released'?`<button class="btn secondary" onclick="transitionExpertAssignment(${a.id},'Release')">Release</button>`:'';return [esc(engagement.title),esc(a.member_display_name_snapshot),esc(a.assignment_role),badge(a.status),esc(a.proposed_by),esc(a.accepted_by),`${taskAction} ${lifecycleAction}`]}));
    const catalogRows=catalog.map(s=>{const action={Draft:'Submit','In Review':'Review',Reviewed:'Approve',Approved:'Publish'}[s.status];return [esc(s.pillar_name),`${esc(s.name)}<br><span class="subtle">${esc(s.service_key)} · v${s.version_no}</span>`,esc(s.member_description),esc(s.internal_scope),badge(s.status),`${action?`<button class="btn" onclick="transitionCatalog(${s.id},'${action}')">${action}</button>`:''} ${['Published','Retired','Superseded'].includes(s.status)?`<button class="btn secondary" onclick="reviseCatalog(${s.id})">Revise</button>`:''} ${s.status==='Published'?`<button class="btn secondary" onclick="transitionCatalog(${s.id},'Retire')">Retire</button>`:''}`]});
    $('#content').innerHTML=`<div class="split"><div class="card"><div class="section-title"><h2>Define SalOPS service</h2></div><p class="subtle">Drafts require independent review, approval, and publication before members can request them.</p><form id="catalog-form"><label>Pillar<select name="pillar_code">${pillars.map(p=>`<option value="${esc(p.pillar_code)}">${esc(p.name)}</option>`).join('')}</select></label><label>Selected industry profile<select name="industry_profile_id"><option value="">General service</option>${industryProfiles.filter(p=>p.status==='Published').map(p=>`<option value="${p.id}">${esc(p.name)} · v${p.version_no}</option>`).join('')}</select></label><label>Service name<input name="name" required></label><label>Member description<textarea name="member_description" required></textarea></label><label>Internal scope<textarea name="internal_scope" required></textarea></label><label>Default deliverables<textarea name="default_deliverables" required></textarea></label><label>Readiness inputs<textarea name="readiness_inputs" required></textarea></label><label>Authorization requirements<textarea name="authorization_requirements" required></textarea></label><label><input type="checkbox" name="member_visible" checked> Available to Protected Members when published</label><div class="form-actions"><button class="btn">Create draft</button></div></form></div><div><div class="section-title"><h2>Service catalog governance</h2><span class="subtle">Versioned lifecycle</span></div>${table(['Pillar','Service','Member scope','Internal scope','Status','Actions'],catalogRows)}</div></div><div class="split"><div class="card"><div class="section-title"><h2>Request operational support</h2></div><p class="subtle">Select a published service when applicable; legacy and governed internal handoffs remain supported.</p><form id="ops-form"><input type="hidden" name="assessment_id" value="${a?.id||''}"><label>Published service<select name="service_catalog_id"><option value="">Manual / governed handoff</option>${catalog.filter(s=>s.status==='Published').map(s=>`<option value="${s.id}">${esc(s.name)} · v${s.version_no}</option>`).join('')}</select></label><label>Request title<input name="title" required></label><label>Priority<select name="priority"><option>Routine</option><option>Priority</option><option>Urgent</option><option>Critical</option></select></label><label>Description<textarea name="description"></textarea></label><div class="form-actions"><button class="btn">Submit request</button></div></form></div><div><div class="section-title"><h2>SalOPS request register</h2><span class="subtle">${rows.length} records</span></div>${table(['ID','Request','Source','Priority','Status','Assigned','Actions'],requestRows)}</div></div><div class="section-title"><h2>Operational engagements</h2><span class="subtle">Governed execution from plan through closure</span></div>${table(['ID','Engagement','Service','Status','Lead','Readiness / task / report state','Actions'],engagementRows)}<div class="section-title"><h2>Engagement readiness</h2><span class="subtle">Controlled prerequisites must be resolved before activation</span></div>${table(['Engagement','Requirement','Member summary','Internal requirement','Status','Actions'],readinessRows)}<div class="section-title"><h2>Estimate and actual position</h2></div>${table(['ID','Engagement','Approved estimate','Approved actuals','Remaining'],varianceRows)}<div class="section-title"><h2>Operational estimates</h2></div>${table(['Engagement','Member summary','Amount','Status','Calculated lines','Actions'],estimateRows)}<div class="section-title"><h2>Actual expenses</h2></div>${table(['Engagement','Incurred','Category','Internal detail','Amount','Status','Actions'],expenseRows)}<div class="section-title"><h2>Invoice-ready statements</h2><span class="subtle">Immutable approval records; not accounting invoices</span></div>${table(['Engagement','Statement','Summary','Billable','Status','Actions'],statementRows)}<div class="section-title"><h2>Operational tasks</h2></div>${table(['Engagement','Task','Assigned','Priority','Status','Actions'],taskRows)}<div class="section-title"><h2>Field reports</h2></div>${table(['Engagement','Occurred','Type','Submitted by','Status','Actions'],reportRows)}`;
    const expertGovernanceHtml=`<div class="split"><div class="card"><div class="section-title"><h2>Register expert profile</h2></div><p class="subtle">Member identity is separated from controlled personnel history. Activation requires independent authority.</p><form id="expert-form"><label>Expert actor identity<input name="expert_actor" required></label><label>Member display name<input name="member_display_name" required></label><label>Member role title<input name="member_role_title" required></label><label>Member biography<textarea name="member_biography" required></textarea></label><label>Member contact summary<textarea name="member_contact_summary"></textarea></label><label>Controlled internal biography<textarea name="internal_biography" required></textarea></label><label>Disciplines<textarea name="disciplines" required></textarea></label><label>Jurisdictions<textarea name="jurisdictions" required></textarea></label><label>Regions<textarea name="regions" required></textarea></label><div class="form-actions"><button class="btn">Create draft profile</button></div></form></div><div><div class="section-title"><h2>Expert qualification register</h2><span class="subtle">Tenant-scoped, governed personnel records</span></div>${table(['Profile','Member identity','Actor','Disciplines','Jurisdictions','Regions','Status','Actions'],profileRows)}</div></div><div class="section-title"><h2>Credential verification</h2><span class="subtle">Independent verification and withdrawal</span></div>${table(['Expert','Credential','Issuer','Jurisdiction','Effective period','Status','Actions'],credentialRows)}<div class="section-title"><h2>Availability</h2><span class="subtle">Operating-period eligibility</span></div>${table(['Expert','Available period','Region','Status','Recorded by'],availabilityRows)}<div class="section-title"><h2>Engagement conflicts</h2><span class="subtle">Disclosure and independent disposition</span></div>${table(['Engagement','Expert','Disclosure','Status','Reviewed by','Actions'],conflictRows)}<div class="section-title"><h2>Expert assignments</h2><span class="subtle">Qualified, conflict-cleared, accepted assignments</span></div>${table(['Engagement','Expert','Role','Status','Proposed by','Accepted by','Actions'],assignmentRows)}`;
    $('#content').insertAdjacentHTML('afterbegin',expertGovernanceHtml);
    const expertForm=$('#expert-form');if(expertForm)expertForm.onsubmit=async e=>{e.preventDefault();const d={};new FormData(e.target).forEach((v,k)=>d[k]=v);await api('/api/salops/experts',{method:'POST',body:JSON.stringify(d)});render();};
    const catalogForm=$('#catalog-form');if(catalogForm)catalogForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const d={};fd.forEach((v,k)=>{if(v!=='')d[k]=k==='industry_profile_id'?Number(v):v});d.member_visible=fd.has('member_visible');await api('/api/salops/catalog/services',{method:'POST',body:JSON.stringify(d)});render();};
  }
  const form=$('#ops-form');
  if(form)form.onsubmit=async e=>{e.preventDefault();const d={};new FormData(e.target).forEach((v,k)=>{if(v!=='')d[k]=['assessment_id','service_catalog_id'].includes(k)?Number(v):v});await api('/api/salops/requests',{method:'POST',body:JSON.stringify(d)});render();};
}
async function transitionCatalog(id,action){const reason=prompt(`Document the ${action.toLowerCase()} authority and basis:`);if(!reason)return;await api(`/api/salops/catalog/services/${id}/transition`,{method:'POST',body:JSON.stringify({action,reason})});render();}
async function reviseCatalog(id){const catalog=await api('/api/salops/catalog/services');const s=catalog.find(x=>x.id===id);if(!s)return;const name=prompt('Revised service name:',s.name);if(!name)return;const member_description=prompt('Revised member description:',s.member_description);if(!member_description)return;const internal_scope=prompt('Revised controlled internal scope:',s.internal_scope);if(!internal_scope)return;const default_deliverables=prompt('Revised default deliverables:',s.default_deliverables);if(!default_deliverables)return;const readiness_inputs=prompt('Revised readiness inputs:',s.readiness_inputs);if(!readiness_inputs)return;const authorization_requirements=prompt('Revised authorization requirements:',s.authorization_requirements);if(!authorization_requirements)return;await api(`/api/salops/catalog/services/${id}/revise`,{method:'POST',body:JSON.stringify({pillar_code:s.pillar_code,name,member_description,internal_scope,default_deliverables,readiness_inputs,authorization_requirements,industry_profile_id:s.industry_profile_id||null,member_visible:!!s.member_visible})});render();}
async function transitionExpertProfile(id,action){const reason=prompt(`Document the ${action.toLowerCase()} authority and basis:`);if(!reason)return;await api(`/api/salops/experts/${id}/transition`,{method:'POST',body:JSON.stringify({action,reason})});render();}
async function addExpertCredential(id){const credential_type=prompt('Credential or qualification:');if(!credential_type)return;const issuer=prompt('Issuer:');if(!issuer)return;const jurisdiction=prompt('Jurisdiction:')||'';const effective_on=prompt('Effective date (YYYY-MM-DD):');if(!effective_on)return;const expires_on=prompt('Expiry date (YYYY-MM-DD, optional):')||'';const evidenceRecords=(await api('/api/evidence')).filter(e=>e.verification_status==='Verified'&&e.lifecycle_status==='Current');const evidence=evidenceRecords.length?chooseGovernedRecord('Verified current evidence (Cancel to continue without evidence)',evidenceRecords,e=>`#${e.id} — ${e.title}`):null;await api(`/api/salops/experts/${id}/credentials`,{method:'POST',body:JSON.stringify({credential_type,issuer,jurisdiction,effective_on,expires_on,evidence_id:evidence?.id||null})});render();}
async function transitionExpertCredential(id,action){const reason=prompt(`Document the ${action.toLowerCase()} authority and basis:`);if(!reason)return;await api(`/api/salops/credentials/${id}/transition`,{method:'POST',body:JSON.stringify({action,reason})});render();}
async function addExpertAvailability(id){const available_from=prompt('Available from (ISO date/time):');if(!available_from)return;const available_until=prompt('Available until (ISO date/time):');if(!available_until)return;const region=prompt('Region:')||'';await api(`/api/salops/experts/${id}/availability`,{method:'POST',body:JSON.stringify({available_from,available_until,region})});render();}
async function discloseExpertConflict(engagementId){const experts=await api('/api/salops/experts');const selected=chooseGovernedRecord('Choose an expert profile',experts,p=>`${p.member_display_name} (${p.status})`);if(!selected)return;const disclosure=prompt('Conflict disclosure:');if(!disclosure)return;await api(`/api/salops/engagements/${engagementId}/conflicts`,{method:'POST',body:JSON.stringify({profile_id:selected.id,disclosure})});render();}
async function reviewExpertConflict(id,decision){const reason=prompt(`Document the independent ${decision.toLowerCase()} review basis:`);if(!reason)return;await api(`/api/salops/conflicts/${id}/review`,{method:'POST',body:JSON.stringify({decision,reason})});render();}
async function proposeExpertAssignment(engagementId){const [experts,conflicts]=await Promise.all([api('/api/salops/experts'),api(`/api/salops/engagements/${engagementId}/conflicts`)]);const expert=chooseGovernedRecord('Choose an active expert profile',experts.filter(p=>p.status==='Active'),p=>p.member_display_name);if(!expert)return;const conflict=chooseGovernedRecord('Choose the cleared conflict review',conflicts.filter(c=>c.profile_id===expert.id&&c.status==='Cleared'),c=>c.review_reason);if(!conflict)return;const assignment_role=prompt('Engagement assignment role:');if(!assignment_role)return;const member_visible=confirm('Show the accepted assignment to the Protected Member?');await api(`/api/salops/engagements/${engagementId}/experts`,{method:'POST',body:JSON.stringify({profile_id:expert.id,conflict_id:conflict.id,assignment_role,member_visible})});render();}
async function transitionExpertAssignment(id,action){const reason=prompt(`Document the ${action.toLowerCase()} basis:`);if(!reason)return;await api(`/api/salops/expert-assignments/${id}/transition`,{method:'POST',body:JSON.stringify({action,reason})});render();}
async function createReadiness(id){const label=prompt('Readiness requirement:');if(!label)return;const member_summary=prompt('Member-safe readiness summary:');if(!member_summary)return;const internal_requirement=prompt('Controlled internal requirement:');if(!internal_requirement)return;const due_at=prompt('Due time (ISO date/time, optional):')||'';const member_visible=confirm('Make this readiness status visible to the Protected Member?');await api(`/api/salops/engagements/${id}/readiness`,{method:'POST',body:JSON.stringify({label,member_summary,internal_requirement,due_at,member_visible})});render();}
async function advanceReadiness(id,status){const reason=prompt(`Document the ${status.toLowerCase()} basis:`);if(!reason)return;await api(`/api/salops/readiness/${id}/transition`,{method:'POST',body:JSON.stringify({status,reason})});render();}
async function authorizeOps(id){const reason=prompt('Authorization basis:');if(!reason)return;const assigned=prompt('Assign to:')||'';await api(`/api/salops/requests/${id}/decision`,{method:'POST',body:JSON.stringify({decision:'Authorized',reason,assigned_to:assigned})});render();}
async function completeOps(id){const summary=prompt('Operational result summary:');if(!summary)return;await api(`/api/salops/requests/${id}/complete`,{method:'POST',body:JSON.stringify({result_summary:summary})});render();}
async function createEngagement(id){const source=(await api('/api/salops/requests')).find(r=>r.id===id&&r.status==='Authorized');if(!source){alert('This request is no longer authorized for engagement planning. Review the current request record before continuing.');return;}const service_type=source.service_name_snapshot||prompt('Confirm service type:',source.title);if(!service_type)return;const objective=prompt('Confirm operational objective:',source.description||source.title);if(!objective)return;const location=prompt('Operating location:')||'';const planned_start=prompt('Planned start (ISO date/time):');if(!planned_start)return;const planned_end=prompt('Planned end (ISO date/time):');if(!planned_end)return;const operational_lead=prompt('Operational lead:');if(!operational_lead)return;const communications_plan=prompt('Controlled communications plan:');if(!communications_plan)return;const member_status_summary=prompt('Member-facing planning summary:');if(!member_status_summary)return;await api(`/api/salops/requests/${id}/engagement`,{method:'POST',body:JSON.stringify({service_type,objective,location,planned_start,planned_end,operational_lead,communications_plan,member_status_summary})});render();}
async function advanceEngagement(id,status){const reason=prompt(`Document the authority basis for ${status}:`);if(!reason)return;const member_status_summary=prompt('Member-facing status summary:');if(!member_status_summary)return;await api(`/api/salops/engagements/${id}/transition`,{method:'POST',body:JSON.stringify({status,reason,member_status_summary})});render();}
async function createOpsTask(id,assignmentId=null){const title=prompt('Task title:');if(!title)return;const instructions=prompt('Controlled task instructions:');if(!instructions)return;const assignments=(await api(`/api/salops/engagements/${id}/experts`)).filter(a=>a.status==='Accepted');const matched=assignmentId?assignments.find(a=>a.id===assignmentId):null;if(assignmentId&&!matched){alert('This expert assignment is no longer accepted for the selected engagement. Review the current assignment record before creating the task.');return;}const assignment_id=matched?matched.id:null;const assigned_to=matched?matched.member_display_name_snapshot:prompt('Assign to:');if(!assigned_to)return;const priority=prompt('Priority: Routine, Priority, Urgent, or Critical','Routine')||'Routine';await api(`/api/salops/engagements/${id}/tasks`,{method:'POST',body:JSON.stringify({title,instructions,assigned_to,priority,assignment_id})});render();}
async function advanceOpsTask(id,status){const reason=prompt(`Document the ${status.toLowerCase()} basis:`);if(!reason)return;const result_summary=status==='Completed'?(prompt('Task result summary:')||''):'';if(status==='Completed'&&!result_summary)return;await api(`/api/salops/tasks/${id}/transition`,{method:'POST',body:JSON.stringify({status,reason,result_summary})});render();}
async function createFieldReport(id,taskId=null){const tasks=await api(`/api/salops/engagements/${id}/tasks`);const task=taskId?tasks.find(t=>t.id===taskId&&t.status!=='Cancelled'):null;if(taskId&&!task){alert('This task is no longer available for field reporting. Refresh and select a current task.');return;}const report_type=prompt('Field report type:',task?`Task Update - ${task.title}`:'Situation Update');if(!report_type)return;const occurred_at=prompt('Occurrence time (ISO date/time):',new Date().toISOString());if(!occurred_at)return;const member_summary=prompt('Member-facing summary:',task?.title||'');if(!member_summary)return;const internal_details=prompt('Controlled internal details:',task?.result_summary||'');if(!internal_details)return;await api(`/api/salops/engagements/${id}/field-reports`,{method:'POST',body:JSON.stringify({task_id:task?.id||null,report_type,occurred_at,member_summary,internal_details})});render();}
async function releaseFieldReport(id){const reason=prompt('Document the release authority and basis:');if(!reason)return;await api(`/api/salops/field-reports/${id}/release`,{method:'POST',body:JSON.stringify({reason})});render();}
async function createEstimate(id){const member_summary=prompt('Member-facing estimate summary:');if(!member_summary)return;const internal_basis=prompt('Controlled estimating basis:');if(!internal_basis)return;const category=prompt('Category: Labor, Travel, Lodging, Per Diem, Equipment, Subcontractor, or Other','Labor')||'Labor';const description=prompt('Line description:');if(!description)return;const quantity=prompt('Quantity:','1');if(!quantity)return;const unit=prompt('Unit:','hour')||'unit';const unit_rate=prompt('Unit rate (USD):');if(!unit_rate)return;await api(`/api/salops/engagements/${id}/estimates`,{method:'POST',body:JSON.stringify({currency:'USD',member_summary,internal_basis,lines:[{category,description,quantity,unit,unit_rate}]})});render();}
async function advanceEstimate(id,status){const reason=prompt(`Document the ${status.toLowerCase()} basis:`);if(!reason)return;await api(`/api/salops/estimates/${id}/transition`,{method:'POST',body:JSON.stringify({status,reason})});render();}
async function createExpense(id){const category=prompt('Category: Labor, Travel, Lodging, Per Diem, Equipment, Subcontractor, or Other','Travel')||'Travel';const description=prompt('Controlled internal expense description:');if(!description)return;const member_description=prompt('Member-safe expense description:');if(!member_description)return;const incurred_on=prompt('Incurred date (YYYY-MM-DD):',new Date().toISOString().slice(0,10));if(!incurred_on)return;const amount=prompt('Amount (USD):');if(!amount)return;const vendor=prompt('Vendor (controlled, optional):')||'';await api(`/api/salops/engagements/${id}/expenses`,{method:'POST',body:JSON.stringify({category,description,member_description,incurred_on,amount,vendor,currency:'USD',reimbursable:true})});render();}
async function advanceExpense(id,status){const reason=prompt(`Document the ${status.toLowerCase()} basis:`);if(!reason)return;await api(`/api/salops/expenses/${id}/transition`,{method:'POST',body:JSON.stringify({status,reason})});render();}
async function createInvoiceReady(id){const billing_period_start=prompt('Billing period start (YYYY-MM-DD):');if(!billing_period_start)return;const billing_period_end=prompt('Billing period end (YYYY-MM-DD):');if(!billing_period_end)return;const service_summary=prompt('Member-facing service summary:');if(!service_summary)return;await api(`/api/salops/engagements/${id}/invoice-statements`,{method:'POST',body:JSON.stringify({billing_period_start,billing_period_end,service_summary})});render();}
async function advanceInvoiceReady(id,status){const reason=prompt(`Document the ${status.toLowerCase()} authority basis:`);if(!reason)return;await api(`/api/salops/invoice-statements/${id}/transition`,{method:'POST',body:JSON.stringify({status,reason})});render();}
function openInvoiceReady(id){window.open(`/api/salops/invoice-statements/${id}/snapshot`,'_blank','noopener');}

async function audit(){const a=await getActiveAssessment();if(!a){$('#content').innerHTML='<div class="notice">No assessment available.</div>';return}const history=await api('/api/audit/assessments/'+a.id);$('#content').innerHTML=`<div class="section-title"><h2>Governed Activity</h2><span class="subtle">Tenant-isolated assessment history</span></div>${table(['Time','User','Action','Entity','ID','Detail'],history.audit.map(r=>[esc(r.ts),esc(r.user_name),badge(r.action),esc(r.entity_type),esc(r.entity_id),esc(r.detail)]))}<div class="section-title"><h2>Version History</h2><span class="subtle">${history.versions.length} snapshots</span></div>${table(['Time','Entity','ID','Version','Changed By','Reason'],history.versions.map(v=>[esc(v.created_at),esc(v.entity_type),v.entity_id,'v'+v.version_no,esc(v.changed_by),esc(v.change_reason)]))}`;}


async function riskAnalytics(){
  const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">Create an assessment first.</div>';return}
  const id=a.id; const [rows,evidence,overrides]=await Promise.all([api('/api/risk/'+id),api('/api/evidence?assessment_id='+id),api('/api/risk_overrides?assessment_id='+id)]);
  const verified=evidence.filter(e=>e.verification_status==='Verified'&&e.lifecycle_status==='Current');
  const effectiveEvidenceIds=new Set(verified.map(e=>e.id));
  const canDecide=!!(accessState?.permissions||[]).includes('decide');
  let panel='';
  if(overridingThreatId){
    const r=rows.find(x=>x.threat_id===overridingThreatId);
    panel=`<div class="card" style="margin-bottom:16px"><div class="section-title"><h2>Record Professional Risk Judgment — ${esc(r?.name||'')}</h2><button class="btn secondary" onclick="cancelRiskOverride()">Cancel</button></div><p class="subtle">This action does not alter calculated current, predicted residual, or validated residual risk. The authenticated actor is recorded as authority. A future review date is required; an overdue judgment stops supplying assigned risk until controlled review.</p><form id="risk-override-form"><div class="form-grid"><label>Calculated Current Risk<input value="${esc((r?.current_band||'')+' '+(r?.current_score??''))}" disabled></label><label>Assigned Risk Score (0–100)<input type="number" min="0" max="100" step="0.1" name="assigned_score" required></label><label>Review Date<input type="date" name="review_date" required></label><label>Supporting Verified Evidence<select name="evidence_id"><option value="">None</option>${verified.map(e=>`<option value="${e.id}">#${e.id} — ${esc(e.title)}</option>`).join('')}</select></label></div><label>Reason / Professional Basis<textarea name="reason" required></textarea></label><div class="form-actions"><button class="btn">Record Professional Judgment</button></div></form></div>`;
  }
  const riskRows=rows.map(r=>{
    const applicable=r.professional_override;
    const record=r.professional_override_record;
    const action=canDecide?(record?`<div class="row-actions"><button class="btn secondary" onclick="beginRiskOverride(${r.threat_id})">Supersede</button><button class="btn secondary" onclick="withdrawRiskOverride(${record.id})">Withdraw</button></div>`:`<button class="btn secondary" onclick="beginRiskOverride(${r.threat_id})">Record Override</button>`):'<span class="subtle">Decision authority required</span>';
    const assigned=applicable?`${badge(r.assigned_risk_band)} ${r.assigned_risk_score}<br><span class="subtle">${esc(applicable.authority)} · ${esc(applicable.created_at)}</span>${applicable.evidence_id?'<br><span class="subtle">Supporting evidence Current</span>':''}`:record?`<span class="badge stale">Not Current</span><br><span class="subtle">${esc(r.professional_override_unavailable_reason)}</span>`:'—';
    return [esc(r.name),`${badge(r.inherent_band)} ${r.inherent_score}`,`${r.capability_effectiveness}%`,`${badge(r.current_band)} ${r.current_score}`,assigned,r.approved_improvements,r.validated_improvements,`${badge(r.predicted_residual_band)} ${r.predicted_residual_score}`,`${badge(r.validated_residual_band)} ${r.validated_residual_score}`,esc(r.risk_methodology_version),badge(r.confidence),badge(r.trend),action];
  });
  $('#content').innerHTML=panel+`<div class="notice"><strong>Calculated risk and professional judgment are separate records.</strong> Current risk is calculated from threat/scenario/capability data. A professional override records an assigned risk for decision context but never overwrites the calculated value and never changes predicted or validated residual-risk mathematics.</div>`+
  table(['Threat / Hazard','Inherent','Capability Effectiveness','Calculated Current','Professional Assigned','Approved','Validated','Predicted Residual','Validated Residual','Method','Confidence','Trend','Professional Judgment'],riskRows)+
  `<div class="section-title"><h2>Professional Risk Override History</h2><span class="subtle">${overrides.length} records</span></div>`+
  table(['ID','Status','Review Lifecycle','Threat','Calculated','Assigned','Authority','Reason','Evidence','Review Date','Created','Actions'],overrides.map(o=>{const evidenceEligible=o.evidence_id==null||effectiveEvidenceIds.has(o.evidence_id);const actions=o.status==='Active'?`<div class="row-actions">${evidenceEligible?`<button class="btn secondary" onclick="reviewRiskOverride(${o.id},'${esc(o.review_date||'')}')">Controlled Review</button>`:'<span class="badge stale">Restore evidence before review</span>'}<button class="btn secondary" onclick="withdrawRiskOverride(${o.id})">Withdraw</button></div>`:esc(o.withdrawn_reason||'');return [o.id,badge(o.status),badge(o.review_lifecycle_status||'Current'),o.threat_id,`${badge(o.calculated_band)} ${o.calculated_score}`,`${badge(o.assigned_band)} ${o.assigned_score}`,esc(o.authority),esc(o.reason),o.evidence_id||'—',esc(o.review_date),esc(o.created_at),actions]}));
  const form=$('#risk-override-form'); if(form) form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const evidenceId=fd.get('evidence_id');await api('/api/risk-overrides',{method:'POST',body:JSON.stringify({assessment_id:id,threat_id:overridingThreatId,assigned_score:Number(fd.get('assigned_score')),reason:fd.get('reason'),authority:currentUser,evidence_id:evidenceId?Number(evidenceId):null,review_date:fd.get('review_date')||''})});overridingThreatId=null;render();};
}
function beginRiskOverride(threatId){overridingThreatId=threatId;render();}
function cancelRiskOverride(){overridingThreatId=null;render();}
async function withdrawRiskOverride(id){const reason=prompt('Document the reason for withdrawing this professional risk override:');if(!reason)return;await api(`/api/risk-overrides/${id}/withdraw`,{method:'POST',body:JSON.stringify({reason})});render();}
async function reviewRiskOverride(id,currentReviewDate=''){const nextReview=prompt('Next professional risk override review date (YYYY-MM-DD). It must be in the future.',currentReviewDate||'');if(!nextReview)return;const outcome=prompt('Document the professional review outcome and continued judgment basis:','');if(!outcome)return;await api(`/api/risk-overrides/${id}/review`,{method:'POST',body:JSON.stringify({next_review_date:nextReview,review_outcome:outcome})});render();}

async function prioritization(){
  const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">No assessment available.</div>';return}
  const id=a.id; const rows=await api('/api/priorities/'+id);
  $('#content').innerHTML=`<div class="notice"><strong>Priority score:</strong> 22% consequence reduction, 18% mission benefit, 12% feasibility, 10% sustainability, 10% compliance impact, 8% staffing impact, 10% cost efficiency, and 10% time to benefit. Every factor remains visible and editable in the underlying improvement record.</div>`+
  table(['Rank','Improvement','Gap Severity','Priority','Initial Cost','Days','Consequence','Mission','Feasibility','Compliance','Staffing','Status'],rows.map((r,i)=>[i+1,esc(r.title),badge(r.gap_severity),`<strong>${r.priority_score}</strong>`,fmtMoney(r.initial_cost),r.implementation_days,r.factors.consequence,r.factors.mission,r.factors.feasibility,r.factors.compliance,r.factors.staffing,badge(r.status)]));
}



async function apiForm(url,formData,opts={}){
  const r=await fetch(url,{method:opts.method||'POST',headers:{...authHeaders(),...(opts.headers||{})},body:formData});
  if(!r.ok) throw new Error(await r.text()); return r.json();
}

async function downloadExecutiveCsv(id){const r=await fetch('/api/report/'+id+'/executive.csv',{headers:authHeaders()});if(!r.ok)throw new Error(await r.text());const blob=await r.blob();const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`salus-thira-executive-${id}.csv`;a.click();URL.revokeObjectURL(u);}
async function openExecutiveReport(id){window.open('/api/report/'+id+'/executive.html','_blank');}

async function downloadAssessmentExport(id){
  const r=await fetch('/api/export/'+id,{headers:authHeaders()});
  if(!r.ok) throw new Error(await r.text());
  const blob=await r.blob(); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=`salus-thira-assessment-${id}.json`; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
}

async function downloadAttachment(id,name){
  const r=await fetch('/api/evidence-attachments/'+id+'/download',{headers:authHeaders()});
  if(!r.ok) throw new Error(await r.text()); const blob=await r.blob(); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=name||'attachment'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
}

async function attachments(){
  const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">No assessment available.</div>';return} const [evidence,files]=await Promise.all([api('/api/evidence?assessment_id='+a.id),api('/api/evidence_attachments?assessment_id='+a.id)]);
  $('#content').innerHTML=`<div class="split"><div class="card"><div class="section-title"><h2>Attach Evidence File</h2></div><p class="subtle">Files are hashed, scanned according to the configured malware policy, and assigned a retention date before promotion to evidence storage.</p><form id="attachment-form"><div class="form-grid"><label>Evidence Record<select name="evidence_id" required>${evidence.map(e=>`<option value="${e.id}">#${e.id} ${esc(e.title)}</option>`).join('')}</select></label><label>File<input name="file" type="file" required></label></div><div class="form-actions"><button class="btn">Upload Evidence File</button></div></form></div><div><div class="section-title"><h2>Evidence File Register</h2><span class="subtle">${files.length} files</span></div>${table(['ID','Evidence','File','Size','Scan','Retention','Legal Hold','SHA-256','Actions'],files.map(f=>[f.id,f.evidence_id,esc(f.original_name),formatBytes(f.size_bytes),badge(f.scan_status||'Unknown'),esc(f.retention_until||''),f.legal_hold?badge('Hold'):badge('No Hold'),`<code>${esc(f.sha256.slice(0,16))}…</code>`,`<div class="row-actions"><button class="btn secondary" onclick="downloadAttachment(${f.id},'${esc(f.original_name).replaceAll("'","\\'")}')">Download</button><button class="btn secondary" onclick="governAttachment(${f.id},${f.legal_hold?1:0},'${esc(f.retention_until||'')}')">Govern</button><button class="btn secondary" onclick="deleteAttachment(${f.id})">Delete</button></div>`]))}</div></div>`;
  const form=$('#attachment-form'); if(form) form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const id=fd.get('evidence_id');fd.delete('evidence_id');await apiForm(`/api/evidence/${id}/attachments`,fd);render();};
}
async function governAttachment(id,held,currentRetention){
  const retention=prompt('Retention-until date/time (ISO 8601). Leave unchanged by canceling.',currentRetention||''); if(retention===null)return;
  const hold=confirm(held?'OK = keep legal hold; Cancel = release legal hold':'OK = place legal hold; Cancel = leave without hold');
  await api(`/api/evidence-attachments/${id}/governance`,{method:'PATCH',body:JSON.stringify({retention_until:retention,legal_hold:held?hold:hold})}); render();
}
async function deleteAttachment(id){if(!confirm('Delete this evidence file? Retention and legal-hold rules will be enforced by the server.'))return;await api(`/api/evidence-attachments/${id}`,{method:'DELETE'});render();}
function formatBytes(v){const n=Number(v||0); if(n<1024)return n+' B'; if(n<1048576)return (n/1024).toFixed(1)+' KB'; return (n/1048576).toFixed(1)+' MB';}

async function governance(){
  const a=await getActiveAssessment(); if(!a){$('#content').innerHTML='<div class="notice">No assessment available.</div>';return}
  const id=a.id;
  const [scopeChanges,events,versions]=await Promise.all([api('/api/scope_changes?assessment_id='+id),api('/api/workflow_events?assessment_id='+id),api('/api/entity_versions?assessment_id='+id)]);
  const states=['Draft','Scope Approved','Evidence Collection','Analysis','SME Review','Salus QA','Client Validation','Findings Finalized','Executive Decisions','Implementation','Validation','Active Monitoring','Reassessment'];
  $('#content').innerHTML=`
    <div class="grid two-col">
      <div class="card"><div class="section-title"><h2>Controlled Workflow</h2></div><p><strong>Current:</strong> ${badge(a.status)} · Assessment v${a.version} · Scope ${a.scope_locked?'Locked':'Open'}</p><form id="transition-form"><label>Move To<select name="to_status">${states.map(x=>`<option ${x===a.status?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label style="margin-top:10px">Reason<textarea name="reason" placeholder="Required for an Assessment Director/System Administrator override."></textarea></label><div class="form-actions"><button class="btn">Record Transition</button></div></form></div>
      <div class="card"><div class="section-title"><h2>Assessment Export</h2></div><p class="subtle">Exports the assessment record, risk analytics, priorities, decisions, reassessment triggers, scope history, workflow history, and revision index as a portable JSON package.</p><button class="btn" onclick="downloadAssessmentExport(${id})">Download Assessment Package</button></div>
    </div>
    <div class="card" style="margin-top:16px"><div class="section-title"><h2>Request Scope / Mission Change</h2></div><p class="subtle">Approved changes increment the assessment version and preserve the locked scope history.</p><form id="scope-form"><input type="hidden" name="assessment_id" value="${id}"><div class="form-grid"><label class="wide">Reason<textarea name="reason" required></textarea></label><label class="wide">New Purpose<textarea name="new_purpose"></textarea></label><label class="wide">New Mission<textarea name="new_mission"></textarea></label><label class="wide">New Scope<textarea name="new_scope"></textarea></label><label class="wide">New Exclusions<textarea name="new_exclusions"></textarea></label><label>Schedule Impact<input name="schedule_impact"></label><label>Cost Impact<input name="cost_impact" type="number" step="0.01" value="0"></label><label class="wide">Assessment Impact<textarea name="assessment_impact"></textarea></label></div><div class="form-actions"><button class="btn">Submit Scope Change</button></div></form></div>
    <div class="section-title"><h2>Scope Change Register</h2></div>${table(['ID','Decision','Reason','Requested By','Approved By','Cost Impact','Created','Actions'],scopeChanges.map(x=>[x.id,badge(x.decision),esc(x.reason),esc(x.requested_by),esc(x.approved_by),fmtMoney(x.cost_impact),esc(x.created_at),x.decision==='Pending'?`<div class="row-actions"><button class="btn" onclick="scopeDecision(${x.id},'Approved')">Approve</button><button class="btn secondary" onclick="scopeDecision(${x.id},'Rejected')">Reject</button></div>`:'']))}
    <div class="section-title"><h2>Workflow History</h2></div>${table(['Time','From','To','Changed By','Reason'],events.map(x=>[esc(x.created_at),badge(x.from_status),badge(x.to_status),esc(x.changed_by),esc(x.reason)]))}
    <div class="section-title"><h2>Revision History</h2></div>${table(['Time','Entity','Record','Revision','Changed By','Reason'],versions.slice(0,100).map(x=>[esc(x.created_at),esc(x.entity_type),x.entity_id,'v'+x.version_no,esc(x.changed_by),esc(x.change_reason)]))}`;
  $('#transition-form').onsubmit=async e=>{e.preventDefault();const d={};new FormData(e.target).forEach((v,k)=>d[k]=v);await api(`/api/assessments/${id}/transition`,{method:'POST',body:JSON.stringify(d)});render();};
  $('#scope-form').onsubmit=async e=>{e.preventDefault();const d={};new FormData(e.target).forEach((v,k)=>{if(v==='')return;d[k]=k==='assessment_id'?Number(v):k==='cost_impact'?Number(v):v});await api('/api/scope-changes',{method:'POST',body:JSON.stringify(d)});render();};
}
async function scopeDecision(id,decision){const reason=prompt(`${decision} scope change — optional decision note:`)||'';await api(`/api/scope-changes/${id}/decision`,{method:'POST',body:JSON.stringify({decision,reason})});render();}

async function renderAssessmentSelector(){
  const host=document.querySelector('.topbar'); if(!host)return; const rows=await api('/api/assessments');
  let sel=document.querySelector('#assessment-select'); if(!sel){sel=document.createElement('select');sel.id='assessment-select';sel.setAttribute('aria-label','Active assessment'); const box=document.querySelector('#identity-box'); if(box)box.insertBefore(sel,box.firstChild);}
  if(rows.length&&!rows.some(x=>x.id===activeAssessmentId)){activeAssessmentId=rows[0].id;localStorage.setItem('salus_assessment_id',String(activeAssessmentId));}
  sel.innerHTML=rows.length?rows.map(a=>`<option value="${a.id}" ${a.id===activeAssessmentId?'selected':''}>${esc(a.organization)} — ${esc(a.name)}</option>`).join(''):'<option>No assessments</option>';
  sel.disabled=!rows.length; sel.onchange=e=>{activeAssessmentId=Number(e.target.value);localStorage.setItem('salus_assessment_id',String(activeAssessmentId));editingRecord=null;render();};
}

function renderIdentity(){
  const host=document.querySelector('.topbar'); if(!host)return; let old=document.querySelector('#identity-box'); if(old)old.remove();
  const box=document.createElement('div'); box.id='identity-box'; box.className='identity-box';
  if(['session','oidc'].includes(systemMode.auth_mode) && accessState){
    currentUser=accessState.user; currentRole=accessState.role;
    box.innerHTML=`<div class="status-pill">${esc(accessState.user)} · ${esc(accessState.role)} · ${esc(accessState.clearance||'Standard')}</div><button class="btn" id="logout-btn">&lt; Sign Out</button>`;
    host.appendChild(box); $('#logout-btn').onclick=logoutSession;
  }else{
    box.innerHTML=`<input id="user-name" value="${esc(currentUser)}" aria-label="User name"/><select id="role-select" aria-label="Role">${['System Administrator','Assessment Director','Lead Assessor','SME Assessor','Client Executive','Program Owner','Contributor','Auditor'].map(r=>`<option ${r===currentRole?'selected':''}>${r}</option>`).join('')}</select><div class="status-pill">Private workspace</div>`;
    const oldPill=host.querySelector(':scope > .status-pill'); if(oldPill)oldPill.remove(); host.appendChild(box);
    $('#user-name').onchange=e=>{currentUser=e.target.value||'Local Operator';localStorage.setItem('salus_user',currentUser)};
    $('#role-select').onchange=e=>{currentRole=e.target.value;localStorage.setItem('salus_role',currentRole);render();window.SalusIntakeCapture?.sync()};
  }
  window.SalusIntakeCapture?.sync();
}

function showLogin(message=''){
  if(systemMode.auth_mode==='oidc'){
    $('#content').innerHTML=`<div class="card" style="max-width:520px;margin:60px auto"><h2>SalCAPA</h2><p class="subtle">Enterprise identity sign-in is required.</p>${message?`<div class="notice">${esc(message)}</div>`:''}<div class="form-actions"><a class="btn" id="oidc-login" href="https://salcapa.salus.solutions/api/auth/oidc/start">Sign in with SSO</a></div></div>`;
    return;
  }
  $('#content').innerHTML=`<div class="card" style="max-width:520px;margin:60px auto"><h2>SalCAPA</h2><p class="subtle">Authenticated session required.</p>${message?`<div class="notice">${esc(message)}</div>`:''}<form id="login-form"><label>Username<input name="username" autocomplete="username" required></label><label style="margin-top:12px">Password<input name="password" type="password" autocomplete="current-password" required></label><div class="form-actions"><button class="btn">Sign In</button></div></form></div>`;
  $('#login-form').onsubmit=async e=>{e.preventDefault();const d={};new FormData(e.target).forEach((v,k)=>d[k]=v);const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});if(!r.ok){showLogin('Invalid username or password.');return}await initialize();};
}
async function logoutSession(){await fetch('/api/auth/logout',{method:'POST'});accessState=null;window.SalusIntakeCapture?.sync();showLogin('Signed out.');}

async function securityReadiness(){
  if(currentRole!=='System Administrator'){ $('#content').innerHTML='<div class="notice">Security and readiness controls require the System Administrator role.</div>'; return; }
  const [ready,events,tenants,users]=await Promise.all([
    api('/api/admin/readiness'),api('/api/admin/security-events?limit=200'),
    api('/api/admin/pilot/tenants'),api('/api/admin/pilot/users')
  ]);
  const db=ready.managed_database_target||{}; const runtime=ready.runtime_database||{}; const secrets=ready.secret_provider||{}; const rate=ready.rate_limit||{}; const tel=ready.telemetry||{};
  const tenantOptions=tenants.filter(t=>t.status==='Active').map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');
  const userRows=users.map(u=>[
    esc(u.display_name),esc(u.email),esc(u.tenant_name),esc(u.role),esc(u.sensitivity_clearance),
    u.identity_bound?badge('Identity Bound'):badge('Invitation Pending'),badge(u.status),
    `<button class="btn secondary" onclick="setPilotUserStatus(${u.id},'${u.status==='Active'?'Disabled':'Active'}')">${u.status==='Active'?'Disable':'Enable'}</button>`
  ]);
  $('#content').innerHTML=`
    <div class="grid two-col">
      <div class="card"><div class="section-title"><h2>Operational Readiness</h2></div><p><strong>Status:</strong> ${ready.ready?badge('Ready'):badge('Needs Attention')}</p><p><strong>Environment:</strong> ${esc(ready.environment)}<br><strong>Authentication:</strong> ${esc(ready.auth_mode)}<br><strong>Storage:</strong> ${esc(ready.storage_backend)}<br><strong>Malware scanning:</strong> ${esc(ready.av_mode)}</p>${ready.issues.length?`<div class="notice">${ready.issues.map(x=>esc(x)).join('<br>')}</div>`:'<div class="notice">No readiness issues detected for the current operating mode.</div>'}</div>
      <div class="card"><div class="section-title"><h2>Infrastructure Controls</h2></div><p><strong>Runtime DB:</strong> ${esc(runtime.provider||'')} · ${runtime.healthy?badge('Healthy'):badge('Attention')}<br><strong>Managed DB target:</strong> ${esc(db.target||'none')} · ${db.configured?(db.healthy?badge('Reachable'):badge('Unreachable')):badge('Not Configured')}<br><strong>Secrets:</strong> ${esc(secrets.backend||'')} · ${secrets.configured?badge('Available'):badge('Unavailable')}<br><strong>Rate limiting:</strong> ${esc(rate.backend||'')} · ${rate.healthy?badge('Healthy'):badge('Attention')}<br><strong>Telemetry:</strong> ${esc(tel.backend||'')} · ${tel.healthy?badge('Healthy'):badge('Attention')}</p><p class="subtle">The active runtime provider is shown above. Governed operation uses managed credentials, managed object storage, protected recovery controls, and sanitized telemetry.</p></div>
    </div>
    <div class="section-title"><h2>Early-Access Accounts</h2><span class="subtle">Administrator-controlled Microsoft Entra admission</span></div>
    <div class="notice"><strong>Invitation-only pilot.</strong> Creating a record authorizes only the named email, organization, role, and clearance. The immutable Microsoft Entra identity is bound on first successful sign-in. Disabling a user immediately revokes active SalCAPA sessions.</div>
    <div class="split" style="margin-top:16px">
      <div class="card">
        <h3>Add Protected Member organization</h3>
        <form id="pilot-tenant-form"><label>Organization name<input name="name" required maxlength="200"></label><label>Organization slug<input name="slug" required maxlength="100" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="example-organization"></label><div class="form-actions"><button class="btn">Add organization &gt;</button></div></form>
      </div>
      <div class="card">
        <h3>Preauthorize user</h3>
        <form id="pilot-user-form"><label>Name<input name="display_name" required maxlength="200"></label><label>Email<input name="email" type="email" required maxlength="320" autocomplete="email"></label><label>Organization<select name="tenant_id" required>${tenantOptions}</select></label><label>Role<select name="role"><option>Contributor</option><option>Client Executive</option><option>Program Owner</option><option>Auditor</option><option>Assessment Director</option><option>Lead Assessor</option><option>SME Assessor</option><option>System Administrator</option></select></label><label>Information clearance<select name="sensitivity_clearance"><option>Standard</option><option>Restricted</option><option>Sensitive</option><option>Highly Sensitive</option></select></label><div class="form-actions"><button class="btn">Authorize account &gt;</button></div></form>
      </div>
    </div>
    <div class="section-title"><h2>Authorized users</h2><span class="subtle">${users.length} governed accounts</span></div>
    ${table(['Name','Email','Organization','Role','Clearance','Entra identity','Status','Action'],userRows)}
    <div class="section-title"><h2>Security Event Register</h2><span class="subtle">${events.length} recent events</span></div>
    ${table(['Time','Severity','Event','User','Source IP','Request ID','Detail'],events.map(e=>[esc(e.ts),badge(e.severity),esc(e.event_type),esc(e.user_name),esc(e.source_ip),`<code>${esc((e.request_id||'').slice(0,12))}</code>`,esc(e.detail)]))}
  `;
  $('#pilot-tenant-form').onsubmit=async e=>{e.preventDefault();const data={};new FormData(e.target).forEach((v,k)=>data[k]=v);await api('/api/admin/pilot/tenants',{method:'POST',body:JSON.stringify(data)});render();};
  $('#pilot-user-form').onsubmit=async e=>{e.preventDefault();const data={};new FormData(e.target).forEach((v,k)=>data[k]=k==='tenant_id'?Number(v):v);await api('/api/admin/pilot/users',{method:'POST',body:JSON.stringify(data)});render();};
}
async function setPilotUserStatus(id,status){
  const verb=status==='Disabled'?'disable':'enable';
  if(!confirm(`Confirm ${verb} for this SalCAPA account?`))return;
  await api(`/api/admin/pilot/users/${id}/status`,{method:'POST',body:JSON.stringify({status})});
  render();
}

async function backups(){
  if(currentRole!=='System Administrator'){ $('#content').innerHTML='<div class="notice">Backup and recovery controls require the System Administrator role.</div>'; return; }
  const [rows,dr,requests]=await Promise.all([api('/api/admin/backups'),api('/api/admin/dr-validations'),api('/api/admin/restore-requests')]);
  $('#content').innerHTML=`<div class="card"><div class="section-title"><h2>Backup & Recovery</h2><button class="btn" id="create-backup">Create Verified Backup</button></div><p class="subtle">Integrity verification and isolated recovery validation are non-destructive. A real restore remains unavailable until scope and reason are documented and an authorized restore request is recorded.</p></div><div class="section-title"><h2>Backup Register</h2><span class="subtle">${rows.length} backups</span></div>${table(['ID','Created','Created By','File','Size','SHA-256','Verified','Restore','Actions'],rows.map(x=>[x.id,esc(x.created_at),esc(x.created_by),esc(x.filename),formatBytes(x.size_bytes),`<code>${esc(x.sha256.slice(0,16))}…</code>`,x.verified_at?badge('Verified'):badge('Not Verified'),esc(x.restore_status||''),`<div class="row-actions"><button class="btn secondary" onclick="verifyBackup(${x.id})">Verify</button><button class="btn secondary" onclick="drValidateBackup(${x.id})">DR Validate</button><button class="btn secondary" onclick="downloadBackup(${x.id},'${esc(x.filename)}')">Download</button><button class="btn" onclick="requestRestore(${x.id})">Request Restore</button></div>`]))}<div class="section-title"><h2>Restore Authority Register</h2><span class="subtle">${requests.length} governed requests</span></div>${table(['ID','Backup','Scope','Status','Requested By','Authorized By','Actions'],requests.map(x=>[x.id,x.backup_id,esc(x.scope),badge(x.status),esc(x.requested_by),esc(x.authorized_by),x.status==='Pending'?`<div class="row-actions"><button class="btn" onclick="decideRestore(${x.id},'Authorized')">Authorize</button><button class="btn secondary" onclick="decideRestore(${x.id},'Rejected')">Reject</button></div>`:x.status==='Authorized'&&systemMode.restore_enabled?`<button class="btn" onclick="executeRestore(${x.backup_id},${x.id})">Execute Restore</button>`:'']))}<div class="section-title"><h2>DR Validation History</h2><span class="subtle">${dr.length} runs</span></div>${table(['Time','Backup','Status','DB Integrity','Assessments','Attachments','Validated By'],dr.map(x=>[esc(x.validated_at),esc(x.filename),badge(x.status),esc(x.database_integrity),x.assessment_count,x.attachment_count,esc(x.validated_by)]))}`;
  $('#create-backup').onclick=async()=>{await api('/api/admin/backups',{method:'POST'});render();};
}
async function verifyBackup(id){const r=await api(`/api/admin/backups/${id}/verify`,{method:'POST'});alert(r.ok?'Backup integrity verified.':'Backup verification failed: '+r.errors.join('; '));render();}
async function drValidateBackup(id){const r=await api(`/api/admin/backups/${id}/dr-validate`,{method:'POST'});alert(r.ok?`DR validation passed. Assessments: ${r.assessment_count}; attachments: ${r.attachment_count}`:'DR validation failed: '+r.errors.join('; '));render();}
async function downloadBackup(id,name){const r=await fetch(`/api/admin/backups/${id}/download`,{headers:authHeaders()});if(!r.ok)throw new Error(await r.text());const blob=await r.blob();const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u);}
async function requestRestore(id){const scope=prompt('Exact restore scope:');if(!scope)return;const reason=prompt('Document the restore reason:');if(!reason)return;await api('/api/admin/restore-requests',{method:'POST',body:JSON.stringify({backup_id:id,scope,reason})});render();}
async function decideRestore(id,decision){const reason=prompt(`Document the ${decision.toLowerCase()} decision basis:`);if(!reason)return;await api(`/api/admin/restore-requests/${id}/decision`,{method:'POST',body:JSON.stringify({decision,reason})});render();}
async function executeRestore(backupId,requestId){if(!confirm('Execute this authorized restore? A pre-restore safety backup will be created first.'))return;await api(`/api/admin/backups/${backupId}/restore?restore_request_id=${requestId}`,{method:'POST'});alert('Authorized restore completed.');location.reload();}

async function initialize(){
  try{systemMode=await fetch('/api/system/mode').then(r=>r.json());}catch(e){systemMode={auth_mode:'prototype',restore_enabled:false};}
  if(['session','oidc'].includes(systemMode.auth_mode)){
    const r=await fetch('/api/auth/session'); if(!r.ok){showLogin();return;} accessState=await r.json(); currentUser=accessState.user; currentRole=accessState.role;
  }else{ try{accessState=await api('/api/system/access');}catch(e){} }
  try{workspaceState=await api('/api/salcapa/workspace');applyWorkspaceNavigation();}catch(e){}
  renderIdentity(); await renderAssessmentSelector(); render();
}
initialize();
